// Heads Up Home — collect-recalls (single-file version for the Supabase dashboard editor).

// Generated by scripts/bundle-for-dashboard.mjs from supabase/functions. Edit those files, not this one.

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2';

// ───────── types.ts ─────────
// Shared shapes used across the backend. Kept dependency-free so they run in
// Supabase Edge Functions (Deno) and in local tests (Node).

type Source = 'fsa' | 'opss' | 'mhra' | 'fss' | 'vmd' | 'hse' | 'eu';

type AlertType = 'recall' | 'allergy' | 'safety-report' | 'safety-alert' | 'action' | 'field-safety-notice' | 'eu-warning';

type RiskLevel = 'serious' | 'high' | 'medium' | 'low' | null;

interface RecallProduct {
  name: string;
  barcode: string | null;
  packSize: string | null;
  batchCodes: string[];
  bestBefore: string | null;
  useBy: string | null;
  batchNotes: string | null;
}

/** One recall in our own format, whichever agency it came from. */
interface Recall {
  id: string;            // "fsa:FSA-PRIN-45-2026" / "opss:2609-0076"
  source: Source;
  sourceRef: string;
  alertType: AlertType;
  title: string;
  summary: string | null;
  advice: string | null;
  riskLevel: RiskLevel;
  categories: string[];
  allergens: string[];
  businesses: string[];
  sourceUrl: string;
  /** The notice's attached PDF, which usually contains the product photos. */
  documentUrl: string | null;
  /** A photo published directly as an image (rare); otherwise filled in later from the PDF. */
  imageUrl: string | null;
  publishedAt: string;   // ISO 8601
  updatedAt: string;     // ISO 8601
  products: RecallProduct[];
}

interface UserProfile {
  userId: string;
  categories: string[];
  allergens: string[];
  alertTiming: 'instant' | 'daily';
}

interface CupboardItem {
  id: number;
  userId: string;
  name: string;
  brand: string | null;
  barcode: string | null;
  dismissedRecalls: string[];
}

type MatchReason = 'cupboard' | 'allergen' | 'category';
type MatchConfidence = 'barcode' | 'likely' | 'possible' | null;

interface Match {
  userId: string;
  recallId: string;
  reason: MatchReason;
  confidence: MatchConfidence;
  cupboardItemId: number | null;
}

// ───────── util.ts ─────────
// Small helpers for the messy reality of government data:
// fields that are sometimes a list and sometimes a single value, HTML in text, etc.

// deno-lint-ignore no-explicit-any
type Json = any;

type FetchFn = (url: string, init?: RequestInit) => Promise<Response>;

/** Always returns an array, whether given nothing, one value or a list. */
function asArray<T>(value: T | T[] | null | undefined): T[] {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

/** First non-empty string among the values given. */
function firstText(...values: unknown[]): string | null {
  for (const v of values) {
    for (const item of asArray(v as unknown)) {
      if (typeof item === 'string' && item.trim()) return item.trim();
    }
  }
  return null;
}

/** Strips HTML and Markdown-ish noise and collapses whitespace. */
function cleanText(input: string | null | undefined): string | null {
  if (!input) return null;
  const text = input
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\/(p|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&rsquo;|&lsquo;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .trim();
  return text || null;
}

/** Shortens text to a whole sentence or word within the limit. */
function shorten(text: string | null, max = 280): string | null {
  if (!text || text.length <= max) return text;
  const cut = text.slice(0, max);
  const sentenceEnd = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('.\n'));
  if (sentenceEnd > max * 0.5) return cut.slice(0, sentenceEnd + 1);
  return cut.slice(0, cut.lastIndexOf(' ')) + '…';
}

/** Normalises any date string the agencies use into ISO 8601. */
function toIso(value: string | null | undefined, fallback?: string): string {
  if (value) {
    const d = new Date(value);
    if (!Number.isNaN(d.getTime())) return d.toISOString();
  }
  return fallback ?? new Date().toISOString();
}

/** Runs `fn` over items with at most `limit` running at once (polite to government servers). */
async function mapLimit<T, R>(items: T[], limit: number, fn: (item: T) => Promise<R>): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i]);
    }
  });
  await Promise.all(workers);
  return results;
}

const USER_AGENT = 'HeadsUpHome/1.0 (recall alerts)';
const TIMEOUT_MS = 30_000; // a stuck download gives up rather than holding up the whole run

/** A server's "no" (as opposed to a dropped connection), with its status code. */
class HttpError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

/** True for answers that won't change if we ask again (404 and friends). */
function isPermanent(err: unknown): boolean {
  return err instanceof HttpError && err.status >= 400 && err.status < 500 && err.status !== 429;
}

/** Tries `fn` up to `attempts` times, waiting a little longer each time. Doesn't retry permanent errors. */
async function withRetries<T>(attempts: number, fn: () => Promise<T>): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (isPermanent(err)) break;
    }
    if (i < attempts - 1) await new Promise((r) => setTimeout(r, 500 * 2 ** i));
  }
  throw lastError;
}

/**
 * attempts: how many tries. headers: extra request headers.
 * complete: says whether text already holds the whole document, so a connection that drops
 * right at the end (some servers hang up without a proper goodbye) still counts as a success.
 */
type GetOptions = { attempts?: number; headers?: Record<string, string>; complete?: (text: string) => boolean };

async function request(fetchFn: FetchFn, url: string, accept: string, extra: Record<string, string> = {}): Promise<Response> {
  const headers = { Accept: accept, 'User-Agent': USER_AGENT, ...extra };
  let res: Response;
  try {
    res = await fetchFn(url, { headers, signal: AbortSignal.timeout(TIMEOUT_MS) });
  } catch (err) {
    throw new Error(`${err instanceof Error ? err.message : String(err)} (no response)`, { cause: err });
  }
  if (!res.ok) throw new HttpError(res.status, `${res.status} ${res.statusText} for ${url}`);
  return res;
}

/** Fetches a web page as text (for sources with no data feed). A dropped download is tried again. */
async function getText(fetchFn: FetchFn, url: string, opts: GetOptions = {}): Promise<string> {
  return await getTextUntil(fetchFn, url, () => false, opts);
}

/**
 * Reads a page from the top and stops as soon as `enough(textSoFar)` says it has what it needs,
 * so a long list (newest first) doesn't have to be downloaded in full. Returns the whole page if it ends first.
 */
async function getTextUntil(fetchFn: FetchFn, url: string, enough: (text: string) => boolean, opts: GetOptions = {}): Promise<string> {
  return await withRetries(opts.attempts ?? 3, async () => {
    const res = await request(fetchFn, url, 'text/html', opts.headers);
    if (!res.body) return await res.text();
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let text = '';
    try {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) return text + decoder.decode();
        text += decoder.decode(value, { stream: true });
        if (enough(text)) return text;
      }
    } catch (err) {
      if (opts.complete?.(text)) return text;
      const how = `encoding ${res.headers.get('content-encoding') ?? 'none'}, transfer ${res.headers.get('transfer-encoding') ?? 'none'}`;
      throw new Error(`${err instanceof Error ? err.message : String(err)} (after ${text.length} characters; ${how})`, { cause: err });
    } finally {
      reader.cancel().catch(() => {}); // stop the rest of the download
    }
  });
}

async function getJson(fetchFn: FetchFn, url: string, attempts = 3): Promise<Json> {
  return await withRetries(attempts, async () => await (await request(fetchFn, url, 'application/json')).json());
}

// ───────── categories.ts ─────────
// Our own category and allergen vocabulary. The app's chips use these keys,
// and both agencies' data is translated into them here.

const CATEGORIES = {
  'food-drink': 'Food & drink',
  'baby-children': 'Baby & children',
  'toys': 'Toys',
  'electrical': 'Electrical',
  'trades-tools': 'Trades & tools',
  'home-furniture': 'Home & furniture',
  'cosmetics': 'Cosmetics',
  'clothing': 'Clothing & accessories',
  'medicines': 'Medicines & health',
  'pets': 'Pets & animals',
  'other': 'Other',
} as const;

type CategoryKey = keyof typeof CATEGORIES;

/** The 14 allergens UK food law requires to be declared. */
const ALLERGENS = {
  celery: 'Celery',
  gluten: 'Gluten',
  crustaceans: 'Crustaceans',
  eggs: 'Eggs',
  fish: 'Fish',
  lupin: 'Lupin',
  milk: 'Milk',
  molluscs: 'Molluscs',
  mustard: 'Mustard',
  'tree-nuts': 'Tree nuts',
  peanuts: 'Peanuts',
  sesame: 'Sesame',
  soya: 'Soya',
  sulphites: 'Sulphites',
} as const;

type AllergenKey = keyof typeof ALLERGENS;

// Ordered: first rule that matches wins, so specific words go before general ones.
const ALLERGEN_RULES: Array<[RegExp, AllergenKey]> = [
  [/peanut|groundnut/, 'peanuts'],
  [/\bnut|almond|hazelnut|walnut|cashew|pecan|brazil|pistachio|macadamia/, 'tree-nuts'],
  [/gluten|wheat|barley|\brye\b|\boats?\b|spelt|kamut|cereal/, 'gluten'],
  [/milk|dairy|lactose|whey|casein/, 'milk'],
  [/\beggs?\b/, 'eggs'],
  [/soy/, 'soya'],
  [/sesame/, 'sesame'],
  [/mustard/, 'mustard'],
  [/celery|celeriac/, 'celery'],
  [/lupin/, 'lupin'],
  [/sulphite|sulfite|sulphur dioxide|sulfur dioxide/, 'sulphites'],
  [/crustacean|prawn|shrimp|crab|lobster|crayfish|langoustine/, 'crustaceans'],
  [/mollusc|mussel|oyster|squid|octopus|clam|scallop|whelk|snail/, 'molluscs'],
  [/\bfish\b|anchov|cod|salmon|tuna|haddock|mackerel/, 'fish'],
];

/** Turns an agency allergen label ("Cereals containing gluten", "Egg") into our key. */
function normaliseAllergen(label: string): AllergenKey | null {
  const text = label.toLowerCase();
  for (const [pattern, key] of ALLERGEN_RULES) {
    if (pattern.test(text)) return key;
  }
  return null;
}

/**
 * Every allergen named in a sentence such as "because of undeclared milk, egg and peanuts".
 * Only looks after words like "undeclared" or "contains", so "Peanut Butter Bars" in a product
 * name isn't mistaken for the problem.
 */
function allergensIn(text: string): AllergenKey[] {
  const m = text.toLowerCase().match(/(?:undeclared|contains?|containing|presence of|not declared[^,]*?:?)\s+(.+)$/);
  if (!m) return [];
  const found = new Set<AllergenKey>();
  for (const part of m[1].split(/,|\band\b|&|\bor\b/)) {
    const key = normaliseAllergen(part);
    if (key) found.add(key);
  }
  return [...found];
}

const BABY_WORDS = /\b(baby|babies|infant|toddler|newborn|nursery|cot|pram|pushchair|buggy|high ?chair|car seat|teether|teething|dummy|dummies|weaning|follow-on|formula milk|children(?:'?s)?|child|kids?)\b/i;

/** True when the text is clearly about babies or children. */
function mentionsChildren(text: string): boolean {
  return BABY_WORDS.test(text);
}

// Pet food: "Raw Frozen Dog Food", "several cat food products", "pet food pouch selections".
const PET_FOOD = /\b(?:dog|dogs|cat|cats|puppy|puppies|kitten|kittens|pet|pets)\s+(?:food|foods|treats?|chews?|biscuits?|meals?|pouch(?:es)?|kibble|dinners?)\b|\b(?:food|treats?|chews?)\s+for\s+(?:dogs|cats|pets|puppies|kittens)\b|\braw\s+(?:dog|cat|pet)\b|\b(?:bird ?seed|fish food|rabbit food|hamster food)\b/i;

// Pet products. "Dog toy" on its own is left alone: in recall notices it's usually a child's
// cuddly dog, so a toy only counts as a pet product when it's clearly for animals.
const PET_PRODUCT = /\bfor\s+(?:dogs|cats|pets|puppies|kittens|rabbits|birds|horses)\b|\bpet\s+(?:beds?|carriers?|collars?|leads?|leash(?:es)?|harness(?:es)?|feeders?|fountains?|heat\w*|mats?|crates?|cages?|grooming|clippers?|hair|toys?|doors?|cameras?|trackers?|bowls?|blankets?|dryers?|products?)\b|\b(?:dog|cat)\s+(?:leads?|leash(?:es)?|collars?|harness(?:es)?|beds?|bowls?|crates?|cages?|kennels?|carriers?|chews?|clippers?|grooming|flaps?|litter|scratch\w*|trees?|trackers?|feeders?|fountains?|coats?)\b|\b(?:aquariums?|fish tanks?|vivariums?|bird ?cages?|hamster cages?|rabbit hutch(?:es)?|chew toys?|squeaky toys?)\b/i;

/** True when a food recall is for pet food rather than food for people. */
function isPetFood(text: string): boolean {
  return PET_FOOD.test(text);
}

/** True when a product recall is clearly for something used by pets. */
function isPetProduct(text: string): boolean {
  return PET_PRODUCT.test(text);
}

// OPSS publishes a "product_category" slug. We match on words in it rather than
// the exact slug so new or renamed OPSS categories still land somewhere sensible.
const OPSS_RULES: Array<[RegExp, CategoryKey]> = [
  [/toy/, 'toys'],
  [/childcare|child|baby|infant/, 'baby-children'],
  [/cosmetic|personal-care|tattoo/, 'cosmetics'],
  [/electric|lighting|battery|batteries|charger|appliance|gas-appliance/, 'electrical'],
  [/tool|machinery|construction|protective|ppe|ladder|pressure|lifting|hand-tool/, 'trades-tools'],
  [/furniture|kitchen|household|home|bedding|fire|candle|chemical/, 'home-furniture'],
  [/cloth|textile|fashion|jewel|footwear|accessor/, 'clothing'],
  [/food|drink/, 'food-drink'],
];

function categoriesForOpss(slug: string | null | undefined, text: string): CategoryKey[] {
  const found = new Set<CategoryKey>();
  const s = (slug ?? '').toLowerCase();
  for (const [pattern, key] of OPSS_RULES) {
    if (pattern.test(s)) {
      found.add(key);
      break;
    }
  }
  if (mentionsChildren(text)) found.add('baby-children');
  if (/pet|animal/.test(s) || isPetProduct(text)) {
    found.delete('toys');
    found.delete('baby-children');
    found.add('pets');
  }
  if (found.size === 0) found.add('other');
  return [...found];
}

function categoriesForFsa(text: string): CategoryKey[] {
  if (isPetFood(text)) return ['pets'];
  const found: CategoryKey[] = ['food-drink'];
  if (mentionsChildren(text)) found.push('baby-children');
  return found;
}

// ───────── fsa.ts ─────────
// Food Standards Agency food alerts.
// API docs: https://data.food.gov.uk/food-alerts/ui/reference
// Licence: Open Government Licence v3.0 — attribution required (shown in the app on each recall).

const FSA_BASE = 'https://data.food.gov.uk/food-alerts/id';

function fsaAlertTypeOf(item: Json): AlertType {
  const types = asArray<string>(item.type).join(' ');
  if (/\/AA\b|\bAA$/.test(types)) return 'allergy';
  if (/\/FAFA\b|\bFAFA$/.test(types)) return 'action';
  return 'recall';
}

function productFrom(p: Json): RecallProduct {
  const batches = asArray<Json>(p.batchDescription);
  const batchCodes = new Set<string>();
  let bestBefore: string | null = null;
  let useBy: string | null = null;
  const notes: string[] = [];
  for (const b of batches) {
    for (const code of [...asArray<string>(b.batchCode), ...asArray<string>(b.lotNumber)]) {
      if (typeof code === 'string' && code.trim()) batchCodes.add(code.trim());
    }
    bestBefore ??= firstText(b.bestBeforeDescription, b.bestBeforeDate);
    useBy ??= firstText(b.useByDescription, b.useByDate);
    const note = firstText(b.batchTextDescription);
    if (note) notes.push(note);
  }
  const barcode = firstText(p.productCode);
  return {
    name: firstText(p.productName) ?? 'Unnamed product',
    barcode: barcode && /^\d{8,14}$/.test(barcode.replace(/\s/g, '')) ? barcode.replace(/\s/g, '') : null,
    packSize: firstText(p.packSizeDescription),
    batchCodes: [...batchCodes],
    bestBefore,
    useBy,
    batchNotes: notes.length ? notes.join('; ') : null,
  };
}

/** The FSA links a customer notice (usually a PDF with a product photo) as "relatedMedia". */
function fsaMedia(relatedMedia: unknown): { documentUrl: string | null; imageUrl: string | null } {
  let documentUrl: string | null = null;
  let imageUrl: string | null = null;
  for (const m of asArray<Json>(relatedMedia as Json)) {
    const url = typeof m === 'string' ? m : firstText(m?.['@id'], m?.url);
    if (!url || !/^https?:\/\//.test(url)) continue;
    if (!imageUrl && /\.(jpe?g|png|webp)(\?|$)/i.test(url)) imageUrl = url;
    if (!documentUrl && /\.pdf(\?|$)/i.test(url)) documentUrl = url;
  }
  return { documentUrl, imageUrl };
}

/** Converts one FSA alert (full view) into our Recall format. */
function normaliseFsaAlert(item: Json): Recall {
  const notation: string = item.notation ?? String(item['@id'] ?? '').split('/').pop();
  const problems = asArray<Json>(item.problem);
  const products = asArray<Json>(item.productDetails).map(productFrom);

  const allergenLabels = [
    ...problems.flatMap((p) => asArray<Json>(p.allergen)),
    ...asArray<Json>(item.productDetails).flatMap((p) => asArray<Json>(p.allergen)),
  ].map((a) => (typeof a === 'string' ? a : a?.label ?? a?.notation ?? ''));
  const allergens = [...new Set(allergenLabels.map(normaliseAllergen).filter((a): a is NonNullable<typeof a> => !!a))];

  const title = cleanText(firstText(item.title, item.shortTitle)) ?? notation;
  const summary = shorten(cleanText(firstText(...problems.map((p) => p.riskStatement), item.description)));
  const advice = shorten(cleanText(firstText(item.consumerAdvice)));
  const businesses = [item.reportingBusiness, ...asArray<Json>(item.otherBusiness)]
    .map((b) => firstText(b?.commonName))
    .filter((b): b is string => !!b);

  const alertType = fsaAlertTypeOf(item);
  const textForCategories = [title, ...products.map((p) => p.name)].join(' ');
  const publishedAt = toIso(item.created);

  return {
    id: `fsa:${notation}`,
    source: 'fsa',
    sourceRef: notation,
    alertType,
    title,
    summary,
    advice,
    riskLevel: null, // FSA doesn't grade risk; the app shows the alert type instead
    categories: categoriesForFsa(textForCategories),
    allergens,
    businesses,
    sourceUrl: firstText(item.alertURL) ?? `https://www.food.gov.uk/news-alerts/alert/${notation.toLowerCase()}`,
    ...fsaMedia(item.relatedMedia),
    publishedAt,
    updatedAt: toIso(item.modified, publishedAt),
    products,
  };
}

/**
 * Fetches every FSA alert published or changed since `since` (ISO date),
 * then each alert's full record so we get batch codes and barcodes.
 */
async function fetchFsaSince(fetchFn: FetchFn, since: string, maxAlerts = 200): Promise<Recall[]> {
  const sinceParam = encodeURIComponent(since);
  const list = await getJson(fetchFn, `${FSA_BASE}?since=${sinceParam}&_limit=${maxAlerts}&_sort=-modified`);
  return fsaRecallsFor(fetchFn, asArray<Json>(list.items));
}

/** Reads the full record of each alert in a list (batches, advice) and converts the published ones. */
async function fsaRecallsFor(fetchFn: FetchFn, items: Json[]): Promise<Recall[]> {
  const list = { items };
  const ids: string[] = asArray<Json>(list.items)
    .map((i) => i.notation ?? String(i['@id'] ?? '').split('/').pop())
    .filter(Boolean);

  const listItems = new Map<string, Json>(asArray<Json>(list.items).map((i) => [i.notation ?? String(i['@id'] ?? '').split('/').pop(), i]));

  // The single-alert endpoint returns the full record (batches, advice) by default.
  // If one alert can't be fetched, fall back to its summary rather than losing every food recall.
  const details = await mapLimit(ids, 5, async (id) => {
    try {
      return await getJson(fetchFn, `${FSA_BASE}/${encodeURIComponent(id)}`);
    } catch {
      return { items: [listItems.get(id)] };
    }
  });
  const recalls: Recall[] = [];
  for (const detail of details) {
    const item = Array.isArray(detail.items) ? detail.items[0] : detail.items ?? detail;
    if (!item) continue;
    const statusLabel = String(item.status?.label ?? 'Published');
    if (!/published/i.test(statusLabel)) continue; // skip withdrawn/draft notices
    recalls.push(normaliseFsaAlert(item));
  }
  return recalls;
}

// ───────── opss.ts ─────────
// Office for Product Safety and Standards (OPSS) product safety alerts, reports and recalls,
// published on GOV.UK. We use GOV.UK's public Search and Content APIs.
// Finder: https://www.gov.uk/product-safety-alerts-reports-recalls
// Licence: Open Government Licence v3.0 — attribution required.

const GOVUK = 'https://www.gov.uk';
const FORMAT = 'product_safety_alert_report_recall';

function opssAlertTypeOf(slug: string | null | undefined): AlertType {
  const s = (slug ?? '').toLowerCase();
  if (s.includes('recall')) return 'recall';
  if (s.includes('alert')) return 'safety-alert';
  return 'safety-report';
}

function riskOf(value: string | null | undefined): RiskLevel {
  const v = (value ?? '').toLowerCase();
  if (v.includes('serious')) return 'serious';
  if (v.includes('high')) return 'high';
  if (v.includes('medium')) return 'medium';
  if (v.includes('low')) return 'low';
  return null;
}

/** Splits GOV.UK body HTML into { heading -> text } using its <h2> headings. */
function sectionsOf(html: string): Map<string, string> {
  const sections = new Map<string, string>();
  const parts = html.split(/<h2[^>]*>/i);
  for (const part of parts.slice(1)) {
    const [headingHtml, ...rest] = part.split(/<\/h2>/i);
    const heading = (cleanText(headingHtml) ?? '').toLowerCase();
    const text = cleanText(rest.join(' '));
    if (heading && text) sections.set(heading, text);
  }
  return sections;
}

/** Text of the first section whose heading matches, trying patterns in priority order. */
function findSection(sections: Map<string, string>, ...patterns: RegExp[]): string | null {
  for (const pattern of patterns) {
    for (const [heading, text] of sections) {
      if (pattern.test(heading)) return text;
    }
  }
  return null;
}

/** "Product Safety Report: Amdelne Tri-Proof Light (2609-0076)" -> name and ref. */
function parseOpssTitle(title: string): { name: string; ref: string | null } {
  const ref = title.match(/\(([0-9]{4}-[0-9]{3,5})\)\s*$/)?.[1] ?? null;
  const name = title
    .replace(/\s*\([0-9]{4}-[0-9]{3,5}\)\s*$/, '')
    .replace(/^(product\s+(safety\s+)?(recall|report|alert))\s*:\s*/i, '')
    .trim();
  return { name: name || title, ref };
}

function productFromBody(name: string, html: string, sections: Map<string, string>): RecallProduct {
  const text = cleanText(html) ?? '';
  const barcode = text.match(/(?:barcode|EAN|GTIN)[^0-9]{0,30}(\d{8,14})/i)?.[1] ?? null;
  const batchSection = findSection(sections, /batch|model|identif/, /product details|product description/);
  const batchCodes = [...(batchSection ?? '').matchAll(/(?:batch|lot|model)(?:\s*(?:number|no\.?|code))?s?\s*[:\-]\s*([A-Z0-9][A-Z0-9\-\/\. ]{1,30})/gi)]
    .map((m) => m[1].trim().replace(/[\.\s]+$/, ''))
    .filter(Boolean);
  return {
    name,
    barcode,
    packSize: null,
    batchCodes: [...new Set(batchCodes)],
    bestBefore: null,
    useBy: null,
    batchNotes: shorten(batchSection, 400),
  };
}

/**
 * OPSS attaches a PDF ("Link to Product Image and PDF") to most notices; the product
 * photos are inside it. Occasionally an image is attached directly, which we use as-is.
 */
function mediaOf(attachments: unknown, body: string): { documentUrl: string | null; imageUrl: string | null } {
  let documentUrl: string | null = null;
  let imageUrl: string | null = null;
  for (const a of asArray<Json>(attachments as Json)) {
    const url = typeof a?.url === 'string' ? a.url : null;
    if (!url) continue;
    const type = String(a.content_type ?? '').toLowerCase();
    if (!imageUrl && (type.startsWith('image/') || /\.(jpe?g|png|webp)$/i.test(url))) imageUrl = url;
    if (!documentUrl && (type === 'application/pdf' || /\.pdf$/i.test(url))) documentUrl = url;
  }
  if (!documentUrl) {
    documentUrl = body.match(/href="(https:\/\/assets\.publishing\.service\.gov\.uk\/[^"]+\.pdf)"/i)?.[1] ?? null;
  }
  if (!imageUrl) {
    imageUrl = body.match(/<img[^>]+src="(https:\/\/assets\.publishing\.service\.gov\.uk\/[^"]+)"/i)?.[1] ?? null;
  }
  return { documentUrl, imageUrl };
}

/** Converts one GOV.UK content item into our Recall format. */
function normaliseOpssItem(content: Json): Recall {
  const meta = content.details?.metadata ?? {};
  const body: string = content.details?.body ?? '';
  const sections = sectionsOf(body);
  const { name, ref: titleRef } = parseOpssTitle(content.title ?? '');
  const basePath: string = content.base_path ?? '';
  const ref = titleRef ?? basePath.match(/(\d{4}-\d{3,5})$/)?.[1] ?? content.content_id;

  const summary = shorten(cleanText(
    findSection(sections, /hazard/, /risk|what is the problem/) ?? content.description,
  ));
  const advice = shorten(cleanText(
    findSection(sections, /what should|what to do|consumer/, /corrective|action/),
  ));
  const categorySlug = firstText(meta.product_category);
  const publishedAt = toIso(meta.product_recall_alert_date ?? content.first_published_at);
  const { documentUrl, imageUrl } = mediaOf(content.details?.attachments, body);

  return {
    id: `opss:${ref}`,
    source: 'opss',
    sourceRef: ref,
    alertType: opssAlertTypeOf(firstText(meta.product_alert_type)),
    title: name,
    summary,
    advice,
    riskLevel: riskOf(firstText(meta.product_risk_level)),
    categories: categoriesForOpss(categorySlug, `${name} ${content.description ?? ''}`),
    allergens: [],
    businesses: [],
    sourceUrl: `${GOVUK}${basePath}`,
    documentUrl,
    imageUrl,
    publishedAt,
    updatedAt: toIso(content.public_updated_at, publishedAt),
    products: [productFromBody(name, body, sections)],
  };
}

/** Lists OPSS notices updated since `since`, then fetches each one's full content. */
async function fetchOpssSince(fetchFn: FetchFn, since: string, maxItems = 300): Promise<Recall[]> {
  const fromDate = since.slice(0, 10); // GOV.UK search filters by whole days
  const links: string[] = [];
  const pageSize = 100;
  for (let start = 0; start < maxItems; start += pageSize) {
    const url = `${GOVUK}/api/search.json?filter_format=${FORMAT}` +
      `&filter_public_timestamp=from:${fromDate}&order=-public_timestamp` +
      `&count=${pageSize}&start=${start}&fields=link,public_timestamp`;
    const page = await getJson(fetchFn, url);
    const results = asArray<Json>(page.results);
    for (const r of results) {
      if (typeof r.link === 'string' && new Date(r.public_timestamp) >= new Date(since)) links.push(r.link);
    }
    if (results.length < pageSize) break;
  }

  const contents = await mapLimit(links, 5, (link) => getJson(fetchFn, `${GOVUK}/api/content${link}`));
  return contents
    .filter((c) => !(c.withdrawn_notice && Object.keys(c.withdrawn_notice).length))
    .map(normaliseOpssItem);
}

// ───────── mhra.ts ─────────
// Medicines and Healthcare products Regulatory Agency (MHRA): medicine recalls and
// device safety information, published on GOV.UK.
// Finder: https://www.gov.uk/drug-device-alerts
// Licence: Open Government Licence v3.0 — attribution required.
//
// We take two of the five message types:
//   medicines-recall-notification  e.g. "Class 2 Medicines Recall: Norgine ..., MOVICOL ..., EL(26)A/41"
//   device-safety-information       e.g. home blood-test strips, insulin pens
// Field safety notices, NHS patient safety alerts and safety roundups are aimed at
// hospitals and clinicians, so they're left out.

const MHRA_TYPES = ['medicines-recall-notification', 'device-safety-information'];

/** "Class 2 Medicines Recall: ..." -> 'high'. Class 1 is the most urgent. */
function riskForClass(title: string): RiskLevel {
  const n = title.match(/\bclass\s*([1-4])\b/i)?.[1];
  return n === '1' ? 'serious' : n === '2' ? 'high' : n === '3' ? 'medium' : n === '4' ? 'low' : null;
}

/**
 * Splits a medicines recall title into its parts:
 * "Class 2 Medicines Recall: Norgine Limited, MOVICOL Plain 13.7g powder, EL(26)A/41"
 *  -> { company: "Norgine Limited", product: "MOVICOL Plain 13.7g powder", ref: "EL(26)A/41" }
 */
function parseMhraTitle(title: string): { company: string | null; product: string; ref: string | null } {
  const colon = title.indexOf(':');
  const isRecall = /recall|notification|drug alert/i.test(title.slice(0, Math.max(colon, 0)));
  if (colon < 0 || !isRecall) {
    // Device safety information: "Nova Biomedical StatStrip ketone test strips: risk of ..."
    const product = (colon > 0 ? title.slice(0, colon) : title).trim();
    const ref = title.match(/\b(DSI\/\d{4}\/\d+)\b/i)?.[1] ?? null;
    return { company: null, product, ref };
  }
  const parts = title.slice(colon + 1).split(',').map((p) => p.trim()).filter(Boolean);
  let ref: string | null = null;
  if (parts.length && /^EL\s*\(\d+\)\s*[A-Z]\s*\/\s*\d+/i.test(parts[parts.length - 1])) ref = parts.pop()!;
  const company = parts.length > 1 ? parts.shift()! : null;
  return { company, product: parts.join(', ') || title, ref };
}

/** The raw HTML of the section whose heading matches, so tables can be read. */
function rawSection(html: string, pattern: RegExp): string | null {
  const parts = html.split(/<h2[^>]*>/i);
  for (const part of parts.slice(1)) {
    const [heading, ...rest] = part.split(/<\/h2>/i);
    if (pattern.test((cleanText(heading) ?? '').toLowerCase())) return rest.join(' ');
  }
  return null;
}

/** Batch numbers and expiry dates from the "Affected Lot Batch Numbers" table. */
function batchesFrom(html: string): { batchCodes: string[]; expiry: string | null } {
  const section = rawSection(html, /batch|lot/);
  if (!section) return { batchCodes: [], expiry: null };
  const rows = [...section.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map((r) =>
    [...r[1].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((c) => cleanText(c[1]) ?? ''));
  if (!rows.length) return { batchCodes: [], expiry: null };
  const header = rows[0].map((h) => h.toLowerCase());
  const batchCol = Math.max(0, header.findIndex((h) => /batch|lot/.test(h)));
  const expiryCol = header.findIndex((h) => /expiry|exp\b|use by/.test(h));
  const body = rows.slice(1).filter((r) => r[batchCol]);
  const batchCodes = [...new Set(body.map((r) => r[batchCol]).filter((b) => /[A-Z0-9]/i.test(b)))];
  const expiries = expiryCol >= 0 ? [...new Set(body.map((r) => r[expiryCol]).filter(Boolean))] : [];
  return { batchCodes, expiry: expiries.length ? expiries.join(', ') : null };
}

function idFor(ref: string | null, basePath: string): string {
  if (ref) return `mhra:${ref.replace(/[^A-Za-z0-9]+/g, '').toUpperCase()}`;
  const slug = basePath.split('/').pop() ?? basePath;
  return `mhra:${slug.slice(-60)}`;
}

/** Converts one GOV.UK MHRA alert into our Recall format. */
function normaliseMhraItem(content: Json): Recall {
  const meta = content.details?.metadata ?? {};
  const body: string = content.details?.body ?? '';
  const sections = sectionsOf(body);
  const title: string = cleanText(content.title) ?? '';
  const alertType = String(meta.alert_type ?? '');
  const isDevice = alertType === 'device-safety-information';
  const { company, product, ref } = parseMhraTitle(title);
  const { batchCodes, expiry } = batchesFrom(body);

  const findSection = (...patterns: RegExp[]) => {
    for (const p of patterns) for (const [h, t] of sections) if (p.test(h)) return t;
    return null;
  };
  const advice = findSection(/advice for patients|to provide to patients|advice for the public|patients and carers/);
  const publishedAt = toIso(meta.issued_date ?? content.first_published_at);
  const basePath: string = content.base_path ?? '';
  const { documentUrl } = mediaOf(content.details?.attachments, body);

  return {
    id: idFor(ref, basePath),
    source: 'mhra',
    sourceRef: ref ?? basePath.split('/').pop() ?? '',
    alertType: isDevice ? 'safety-alert' : 'recall',
    title: isDevice ? title : product,
    summary: shorten(cleanText(content.description) ?? findSection(/summary|background/)),
    advice: shorten(advice ?? null, 400),
    riskLevel: isDevice ? null : riskForClass(title),
    categories: mentionsChildren(title) ? ['medicines', 'baby-children'] : ['medicines'],
    allergens: [],
    businesses: company ? [company] : [],
    sourceUrl: `${GOVUK}${basePath}`,
    documentUrl,
    imageUrl: null,
    publishedAt,
    updatedAt: toIso(content.public_updated_at, publishedAt),
    products: [{
      name: product,
      barcode: null,
      packSize: null,
      batchCodes,
      bestBefore: expiry ? `Expiry: ${expiry}` : null,
      useBy: null,
      batchNotes: null,
    }],
  };
}

/** Lists MHRA medicine recalls and device safety information since `since`, then reads each one. */
async function fetchMhraSince(fetchFn: FetchFn, since: string, maxItems = 100): Promise<Recall[]> {
  const fromDate = since.slice(0, 10);
  const links = new Set<string>();
  for (const type of MHRA_TYPES) {
    const url = `${GOVUK}/api/search.json?filter_format=medical_safety_alert&filter_alert_type=${type}` +
      `&filter_public_timestamp=from:${fromDate}&order=-public_timestamp&count=${maxItems}&fields=link,public_timestamp`;
    const page = await getJson(fetchFn, url);
    for (const r of asArray<Json>(page.results)) {
      if (typeof r.link === 'string' && new Date(r.public_timestamp) >= new Date(since)) links.add(r.link);
    }
  }
  const contents = await mapLimit([...links], 5, (link) => getJson(fetchFn, `${GOVUK}/api/content${link}`));
  return contents
    .filter((c) => !(c.withdrawn_notice && Object.keys(c.withdrawn_notice).length))
    .filter((c) => MHRA_TYPES.includes(String(c.details?.metadata?.alert_type ?? '')))
    .map(normaliseMhraItem);
}

// ───────── vmd.ts ─────────
// Veterinary Medicines Directorate (VMD): recalls of animal medicines, published on GOV.UK as news stories.
// Titles vary: "Product defect recall alert: X", "X - product defect recall alert", "Batch recall alert for X",
// "Batch recall - X", "X recall alert".
// Most notices are short letters: "We wish to inform veterinarians that <company> has initiated a Class II
// recall of X due to <reason>." The batches follow as a table (Batch number | Expiry date, sometimes with a
// Product column), a list, or a line such as "Bulk Batch Number: 5E10".
// Example: https://www.gov.uk/government/news/batch-recall-kelactin-and-pgf-veyx-forte
// Licence: Open Government Licence v3.0 — attribution required.
//
// Withdrawn alerts (the VMD withdraws them once a recall is over) are skipped.

const VMD_ORG = 'veterinary-medicines-directorate';

/** True for the VMD's recall notices, as opposed to its other news. */
function isVmdRecallTitle(title: string): boolean {
  return /\brecall/i.test(title);
}

const TITLE_WORDS = String.raw`(?:product (?:defect )?recall(?: alert)?|batch recall(?: alert)?|recall alert|product recall)`;
const TITLE_START = new RegExp(String.raw`^\s*${TITLE_WORDS}\s*(?::|for\b|-|–)?\s*`, 'i');
const TITLE_END = new RegExp(String.raw`\s*(?:-|–|:)?\s*${TITLE_WORDS}\s*$`, 'i');

/** The product's name from the notice title, without the "recall alert" wording. */
function vmdProductName(title: string): string {
  const name = title.replace(/^\s*\[withdrawn\]\s*/i, '').replace(TITLE_START, '').replace(TITLE_END, '').trim();
  return name || title.trim();
}

/**
 * "Label: value" pairs from a notice, whether written as two-column table rows or as lines
 * such as "Bulk Batch Number: 5E10". Labels are lower case.
 */
function vmdFields(html: string): Map<string, string> {
  const fields = new Map<string, string>();
  const add = (label: string, value: string) => {
    const key = label.toLowerCase().replace(/[:\s]+$/, '').trim();
    if (key && value && key.length <= 60 && !fields.has(key)) fields.set(key, value.trim());
  };
  for (const row of html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)) {
    const cells = [...row[1].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((c) => cleanText(c[1]) ?? '');
    if (cells.length === 2) add(cells[0], cells[1]);
  }
  for (const line of textLines(html)) {
    const m = line.match(/^([A-Za-z][A-Za-z ()/'’-]{1,50}):\s*(\S.*)$/);
    if (m) add(m[1], m[2]);
  }
  return fields;
}

function fieldLike(fields: Map<string, string>, pattern: RegExp, not?: RegExp): string[] {
  return [...fields].filter(([k]) => pattern.test(k) && !(not && not.test(k))).map(([, v]) => v);
}

/** The notice's text outside tables, one paragraph, list item or line per entry. */
function textLines(html: string): string[] {
  return (cleanText(html.replace(/<table[\s\S]*?<\/table>/gi, '\n')) ?? '').split('\n').map((l) => l.trim()).filter(Boolean);
}

function sentencesOf(html: string): string[] {
  return textLines(html).join(' ').split(/(?<=[.!?])\s+(?=[A-Z])/).map((s) => s.trim()).filter(Boolean);
}

const capitalise = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const asSentence = (s: string) => capitalise(s.trim()).replace(/[.;:,\s]*$/, '.');

/** A batch code: letters and digits, at least one digit, and not just a year. */
function asBatchCode(token: string | undefined): string | null {
  const t = (token ?? '').trim().replace(/[.,;:)]+$/, '');
  if (!/^[A-Z0-9][A-Z0-9-]{2,19}$/i.test(t) || !/\d/.test(t) || /^(19|20)\d\d$/.test(t)) return null;
  return t;
}

function expiryIn(text: string): string | null {
  const m = text.match(/expir\w*(?:\s+date)?(?:\s+(?:of|is))?\s*[:\-–]?\s*([0-9]{1,2}(?:\s*[A-Za-z]+|\/[0-9]{1,2})?[\s/]*[0-9]{2,4}|[A-Za-z]+\s+[0-9]{4})/i);
  return m ? m[1].trim() : null;
}

type VmdBatch = { product: string | null; batch: string; expiry: string | null };

/** Batches from any table with a "Batch" or "Lot" column (and maybe Product and Expiry columns). */
function vmdTableBatches(html: string): VmdBatch[] {
  const out: VmdBatch[] = [];
  for (const table of html.matchAll(/<table[^>]*>([\s\S]*?)<\/table>/gi)) {
    const rows = [...table[1].matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map((r) =>
      [...r[1].matchAll(/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi)].map((c) => cleanText(c[1]) ?? ''));
    if (rows.length < 2) continue;
    const header = rows[0].map((h) => h.toLowerCase());
    const b = header.findIndex((h) => /batch|lot/.test(h));
    if (b < 0) continue;
    const e = header.findIndex((h) => /expiry|exp\b|use by/.test(h));
    const p = header.findIndex((h, i) => i !== b && /product|name|presentation/.test(h));
    // A product named once for several batches (merged or blank cells) carries down to the rows below.
    let prev: string[] = [];
    for (const raw of rows.slice(1)) {
      const row = raw.length < header.length ? [...prev.slice(0, header.length - raw.length), ...raw] : [...raw];
      if (p >= 0 && !row[p] && prev[p]) row[p] = prev[p];
      prev = row;
      for (const part of (row[b] ?? '').split(/,|;|&|\band\b|\n/)) {
        const code = asBatchCode(part);
        if (code) out.push({ product: p >= 0 ? row[p] || null : null, batch: code, expiry: e >= 0 ? row[e] || null : null });
      }
    }
  }
  return out;
}

/** Batches written in the text: "Batch number: 5E10", "batch 23K019, expiry 11/2026", or a list after "the following batches". */
function vmdTextBatches(html: string): VmdBatch[] {
  const out: VmdBatch[] = [];
  let listContext = false;
  for (const line of textLines(html)) {
    const label = line.match(/^(?:bulk\s+)?(?:batch|lot)(?:es)?\s*(?:numbers?|nos?\.?|codes?)?\s*(?:\([^)]*\))?\s*[:\-–]\s*(.+)$/i);
    if (label) {
      for (const part of label[1].split(/,|;|&|\band\b/)) {
        const code = asBatchCode(part.trim().split(/\s+/)[0]);
        if (code) out.push({ product: null, batch: code, expiry: expiryIn(part) ?? expiryIn(line) });
      }
      listContext = false;
      continue;
    }
    const lead = asBatchCode(line.split(/[\s,(]+/)[0]);
    if (listContext && lead) {
      out.push({ product: null, batch: lead, expiry: expiryIn(line) });
      continue;
    }
    for (const m of line.matchAll(/\b(?:batch|lot)(?:es)?\s+(?:(?:numbers?|no\.?|is|are|code)\s+)*:?\s*([A-Z0-9][A-Z0-9-]*)/gi)) {
      const code = asBatchCode(m[1]);
      if (code) out.push({ product: null, batch: code, expiry: expiryIn(line.slice(m.index ?? 0)) });
    }
    listContext = /\b(batch|batches|lot|lots)\b/i.test(line);
  }
  const seen = new Set<string>();
  return out.filter((b) => !seen.has(b.batch) && seen.add(b.batch));
}

/** Kept for older callers: batch codes and expiry, from a table or the text. */
function vmdBatches(html: string): { batchCodes: string[]; expiry: string | null } {
  const found = vmdTableBatches(html);
  const all = found.length ? found : vmdTextBatches(html);
  const expiries = [...new Set(all.map((b) => b.expiry).filter((e): e is string => !!e))];
  return { batchCodes: [...new Set(all.map((b) => b.batch))], expiry: expiries.length ? expiries.slice(0, 3).join(', ') : null };
}

/** Why it's recalled: the "due to ..." part of the notice, e.g. "Visible particles present in the vials." */
const CAUSE = /\b(?:due to|because of|because|as a result of|owing to|as (?!a precaution)(?=(?:the|some|these|this|a)\b))\s*(?:the\s+(?=(?:possibility|potential|risk|presence|finding)))?(.+)$/i;
const FINDING = /\b(?:following|after|prompted by)\s+(?:the |a |an )?(?:observation|identification|detection|discovery|finding|report|complaint|confirmation)s?\s+(?:of|that)\s+(.+)$/i;
const PROBLEM = /\b(may not|may be|might|could|found|identified|observed|detected|risk|failed|out of specification|contaminat\w*|particles?|leak\w*|incorrect\w*|mislabel\w*)\b/i;
const NOT_A_REASON = /^we (?:wish|would like) to|\bhas initiated\b|\bhave initiated\b|\b(contact|e-?mail|telephone|tel\.?|phone|queries|enquiries)\b|\b(should|are asked|please)\b/i;

function vmdReason(html: string): string | null {
  const sentences = sentencesOf(html);
  const ordered = [...sentences.filter((s) => /recall/i.test(s)), ...sentences.filter((s) => !/recall/i.test(s))];
  for (const s of ordered) {
    const m = s.match(CAUSE) ?? s.match(FINDING);
    if (m && m[1].length > 8) return asSentence(m[1]);
    const r = s.match(/^the reason for (?:the|this) recall (?:relates to|is) (?:the )?(?:identification|observation|detection|discovery|presence) of (.+)$/i);
    if (r && r[1].length > 8) return asSentence(r[1]);
  }
  // Otherwise the first sentence that describes a problem, e.g. "The affected batches may not ...".
  const problem = sentences.find((s) => PROBLEM.test(s) && !NOT_A_REASON.test(s));
  if (problem) {
    return asSentence(problem.replace(/^(?:it has been (?:identified|found|confirmed|observed|reported) that|this is because|the reason for (?:the|this) recall is(?: that)?)\s*/i, ''));
  }
  return null;
}

/** The notice's opening line without "We wish to inform ... that". */
function openingLine(html: string): string | null {
  const first = sentencesOf(html)[0];
  if (!first) return null;
  return asSentence(first.replace(/^we (?:wish|would like) to (?:inform|advise|notify|make)\b.*?\bthat\s+/i, ''));
}

/** What to do: sentences asking people to act, plus who the recall is aimed at. */
function vmdAction(html: string): string | null {
  const asks = sentencesOf(html).filter((s) =>
    !/^we (?:wish|would like) to/i.test(s) &&
    /\b(should|are (?:being )?asked|asked to|please|return|quarantine|examine|check (?:their|your|stock|inventory))\b/i.test(s));
  const level = sentencesOf(html).join(' ').match(/recall (?:to|at) (?:the )?([a-z /]+?) level/i)?.[1];
  const parts = asks.slice(0, 2);
  if (level) parts.push(`This recall is at ${level.toLowerCase()} level.`);
  return parts.length ? parts.join(' ') : null;
}

/** Converts one GOV.UK VMD recall into our Recall format. */
function normaliseVmdItem(content: Json): Recall {
  const body: string = content.details?.body ?? '';
  const title: string = cleanText(content.title) ?? '';
  const name = vmdProductName(title);
  const basePath: string = content.base_path ?? '';
  const slug = basePath.split('/').pop() ?? basePath;
  const sections = sectionsOf(body);
  const findSection = (...patterns: RegExp[]) => {
    for (const p of patterns) for (const [h, t] of sections) if (p.test(h)) return t;
    return null;
  };
  const fields = vmdFields(body);
  const publishedAt = toIso(content.first_published_at ?? content.public_updated_at);
  const description = cleanText(content.description);
  const descriptionUseful = description && !/^(?:product (?:defect )?|batch )?recall/i.test(description)
    && description.toLowerCase() !== title.toLowerCase();

  // What's wrong: the notice's own reason first, as the GOV.UK description often repeats the title.
  const summary = fieldLike(fields, /reason|nature of|defect|problem|issue/, /recall alert/)[0]
    ?? findSection(/reason|nature of|defect|problem|issue/)
    ?? vmdReason(body)
    ?? (descriptionUseful ? description : null)
    ?? openingLine(body)
    ?? description;
  const advice = findSection(/action|advice|what to do/)
    ?? fieldLike(fields, /action|advice|what to do/)[0]
    ?? vmdAction(body);

  const notes = [...fields].filter(([k]) => /packing run|product code|\bma\b|marketing authori[sz]ation/.test(k))
    .map(([k, v]) => `${(k.charAt(0).toUpperCase() + k.slice(1)).replace(/\bma\b/i, 'MA')}: ${v}`);
  const productField = fieldLike(fields, /^product(?: name)?$/)[0];
  const mainName = productField && productField.length <= 160 ? productField : name;

  // One product per name in the batch table, or one product for the whole notice.
  const tableBatches = vmdTableBatches(body);
  const textBatches = tableBatches.length ? [] : vmdTextBatches(body);
  // Last resort: a two-column "Batch number | A1, B2" row.
  const fieldExpiry = fieldLike(fields, /expiry|use by/)[0] ?? null;
  const fieldBatches: VmdBatch[] = tableBatches.length || textBatches.length ? [] : fieldLike(fields, /\b(batch|lot)\b/, /packing|run/)
    .flatMap((v) => v.split(/,|;|&|\band\b/))
    .map((part) => asBatchCode(part.trim().split(/\s+/)[0]))
    .filter((c): c is string => !!c)
    .map((batch) => ({ product: null, batch, expiry: fieldExpiry }));
  const batches = [...tableBatches, ...textBatches, ...fieldBatches]
    .map((b) => ({ ...b, expiry: b.expiry ?? fieldExpiry }));
  const groups = new Map<string, VmdBatch[]>();
  for (const b of batches) {
    const key = b.product ?? mainName;
    groups.set(key, [...(groups.get(key) ?? []), b]);
  }
  if (!groups.size) groups.set(mainName, []);
  const products = [...groups].map(([productName, list]) => {
    const expiries = [...new Set(list.map((b) => b.expiry).filter((e): e is string => !!e))];
    return {
      name: productName,
      barcode: null,
      packSize: null,
      batchCodes: [...new Set(list.map((b) => b.batch))],
      bestBefore: expiries.length ? `Expiry: ${expiries.length > 4 ? `${expiries.slice(0, 4).join(', ')} and others` : expiries.join(', ')}` : null,
      useBy: null,
      batchNotes: notes.length ? notes.join('\n') : null,
    };
  });
  const { documentUrl } = mediaOf(content.details?.attachments, body);

  return {
    id: `vmd:${slug.slice(-60)}`,
    source: 'vmd',
    sourceRef: slug,
    alertType: 'recall',
    title: name,
    summary: shorten(summary),
    advice: shorten(advice, 400),
    riskLevel: null,
    categories: ['pets'],
    allergens: [],
    businesses: [],
    sourceUrl: `${GOVUK}${basePath}`,
    documentUrl,
    imageUrl: null,
    publishedAt,
    updatedAt: toIso(content.public_updated_at, publishedAt),
    products,
  };
}

/** Lists the VMD's recall notices since `since`, then reads each one. */
async function fetchVmdSince(fetchFn: FetchFn, since: string, maxItems = 50): Promise<Recall[]> {
  const fromDate = since.slice(0, 10);
  const url = `${GOVUK}/api/search.json?filter_organisations=${VMD_ORG}&filter_content_store_document_type=news_story` +
    `&filter_public_timestamp=from:${fromDate}&order=-public_timestamp&count=${maxItems}&fields=link,title,public_timestamp`;
  const page = await getJson(fetchFn, url);
  const links = asArray<Json>(page.results)
    .filter((r) => typeof r.link === 'string' && isVmdRecallTitle(String(r.title ?? '')))
    .filter((r) => new Date(r.public_timestamp) >= new Date(since))
    .map((r) => r.link as string);
  const contents = await mapLimit([...new Set(links)], 4, (link) => getJson(fetchFn, `${GOVUK}/api/content${link}`));
  return contents
    .filter((c) => !(c.withdrawn_notice && Object.keys(c.withdrawn_notice).length))
    .filter((c) => isVmdRecallTitle(String(c.title ?? '')))
    .map(normaliseVmdItem);
}

// ───────── fss.ts ─────────
// Food Standards Scotland (FSS) food and allergy alerts.
// Listing: https://www.foodstandards.gov.scot/alerts
//
// Most alerts on this page are the UK-wide FSA alerts (linked to alerts.food.gov.uk),
// which we already collect from the FSA. We only take the ones hosted on FSS's own site,
// which are Scotland-only. FSS has no data feed, so we read the public alerts page politely:
// one listing request per hourly run, then one request per new alert.

const FSS_BASE = 'https://www.foodstandards.gov.scot';

const MONTHS = 'January|February|March|April|May|June|July|August|September|October|November|December';

interface FssListing {
  url: string;
  slug: string;
  title: string;
  date: string | null; // ISO, if the listing shows one
}

/** Finds the Scotland-only alerts on the listing page. */
function parseFssListing(html: string): FssListing[] {
  const found = new Map<string, FssListing>();
  const linkRe = /<a\b[^>]*href="((?:https:\/\/www\.foodstandards\.gov\.scot)?\/alerts\/([a-z0-9][a-z0-9-]{8,}))"[^>]*>([\s\S]*?)<\/a>/gi;
  for (const m of html.matchAll(linkRe)) {
    const slug = m[2];
    const title = cleanText(m[3]);
    if (!title || title.length < 12 || found.has(slug)) continue;
    // The date sits just before or after the link: take the closest one.
    const start = m.index!;
    const end = start + m[0].length;
    const from = Math.max(0, start - 400);
    let date: string | null = null;
    let best = Infinity;
    for (const d of html.slice(from, end + 400).matchAll(new RegExp(`\\b(\\d{1,2})\\s+(${MONTHS})\\s+(\\d{4})\\b`, 'g'))) {
      const at = from + d.index!;
      const distance = at < start ? start - at : at > end ? at - end : 0;
      if (distance < best) {
        best = distance;
        date = toIso(`${d[1]} ${d[2]} ${d[3]} 12:00 UTC`);
      }
    }
    found.set(slug, { url: m[1].startsWith('http') ? m[1] : `${FSS_BASE}${m[1]}`, slug, title, date });
  }
  return [...found.values()];
}

/** "Dunnet Bay Distillers recalls Rock Rose Gin ... because of undeclared sulphites" */
function parseFssTitle(title: string): { business: string | null; product: string; reason: string | null } {
  const t = title.replace(/^(update\s*\d*:\s*)/i, '').replace(/^(allergy alert|food alert|product recall)[:\s-]+/i, '').trim();
  const m = t.match(/^(.+?)\s+recalls?\s+(.+?)(?:\s+(because|due to|as)\s+(.+))?$/i);
  if (!m) return { business: null, product: t, reason: null };
  return { business: m[1].trim(), product: m[2].trim(), reason: m[4] ? `${m[3]} ${m[4]}`.trim() : null };
}

function metaDescription(html: string): string | null {
  const m = html.match(/<meta[^>]+(?:name|property)="(?:description|og:description)"[^>]+content="([^"]*)"/i)
    ?? html.match(/<meta[^>]+content="([^"]*)"[^>]+(?:name|property)="(?:description|og:description)"/i);
  return m ? cleanText(m[1]) : null;
}

/** The text under a heading such as "What to do" on an alert page. */
function sectionText(html: string, pattern: RegExp): string | null {
  const parts = html.split(/<h[23][^>]*>/i);
  for (const part of parts.slice(1)) {
    const [heading, ...rest] = part.split(/<\/h[23]>/i);
    if (pattern.test((cleanText(heading) ?? '').toLowerCase())) {
      const text = cleanText(rest.join(' ').split(/<h[1-3][^>]*>/i)[0]);
      if (text) return text;
    }
  }
  return null;
}

/** The publication date on an alert page, from a <time> tag or the first written date. */
function pageDate(html: string): string | null {
  const t = html.match(/<time[^>]+datetime="([^"]+)"/i)?.[1];
  if (t && !Number.isNaN(new Date(t).getTime())) return new Date(t).toISOString();
  const d = (cleanText(html) ?? '').match(new RegExp(`\\b(\\d{1,2})\\s+(${MONTHS})\\s+(\\d{4})\\b`));
  return d ? toIso(`${d[1]} ${d[2]} ${d[3]} 12:00 UTC`) : null;
}

/** Converts one listing entry (plus its page, if we could read it) into our Recall format. */
function normaliseFss(item: FssListing, page: string | null): Recall {
  const { business, product, reason } = parseFssTitle(item.title);
  const isAllergy = /^allergy-alert/.test(item.slug) || /undeclared|allerg/i.test(item.title);
  const alertType: AlertType = isAllergy ? 'allergy' : 'recall';
  const summary = page
    ? sectionText(page, /risk|problem|why|issue/) ?? metaDescription(page)
    : null;
  const advice = page ? sectionText(page, /what to do|action|advice/) : null;
  const batch = page ? sectionText(page, /product details|batch|best before|use by/) : null;
  const publishedAt = item.date ?? (page ? pageDate(page) : null) ?? new Date().toISOString();

  return {
    id: `fss:${item.slug.slice(0, 80)}`,
    source: 'fss',
    sourceRef: item.slug,
    alertType,
    title: item.title.replace(/^(update\s*\d*:\s*)/i, '').trim(),
    summary: shorten(summary ?? (reason ? `Recalled ${reason}.` : null)),
    advice: shorten(advice),
    riskLevel: null,
    categories: categoriesForFsa(item.title),
    allergens: allergensIn(item.title),
    businesses: business ? [business] : [],
    sourceUrl: item.url,
    documentUrl: null,
    imageUrl: null,
    publishedAt,
    updatedAt: publishedAt,
    products: [{
      name: product,
      barcode: null,
      packSize: null,
      batchCodes: [],
      bestBefore: null,
      useBy: null,
      batchNotes: shorten(batch, 400),
    }],
  };
}

/** Reads the FSS alerts page and returns Scotland-only alerts newer than `since`. */
async function fetchFssSince(fetchFn: FetchFn, since: string): Promise<Recall[]> {
  const listing = parseFssListing(await getText(fetchFn, `${FSS_BASE}/alerts`));
  const fresh = listing.filter((i) => !i.date || new Date(i.date) >= new Date(new Date(since).getTime() - 86400_000));
  const pages = await mapLimit(fresh.slice(0, 20), 2, async (i) => {
    try { return await getText(fetchFn, i.url); } catch { return null; }
  });
  return fresh.slice(0, 20).map((item, idx) => normaliseFss(item, pages[idx]));
}

// ───────── mhra-fsn.ts ─────────
// MHRA Field Safety Notices (FSNs): manufacturers' safety notices for medical devices, published on
// GOV.UK as weekly lists, e.g. "Field Safety Notices: 29 September to 3 October 2025".
// Each notice in a list is an <h3> "Manufacturer: Device", followed by lines for the date, the type of
// device, the model and an "MHRA reference" link to the manufacturer's notice (a PDF).
//
// Most FSNs are for hospital equipment. We keep only devices people use at home, such as glucose
// meters, insulin pens, inhalers, CPAP machines, hearing aids and mobility aids.
// Licence: Open Government Licence v3.0 — attribution required.

const FSN_ALERT_TYPE = 'field-safety-notices';

const HOME_DEVICE = new RegExp(String.raw`\b(` + [
  'blood glucose', 'glucose (?:meter|monitor|sensor|test)', 'continuous glucose', 'cgm', 'freestyle libre', 'libre',
  'dexcom', 'omnipod', 'ketone', 'test strips?', 'lancets?', 'lancing device', 'insulin', 'pen needles?',
  'injection pen', 'auto-?injector', 'adrenaline', 'epinephrine', 'epipen', 'inhalers?', 'spacer', 'nebuli[sz]ers?',
  'c?pap', 'sleep apn(?:o)?ea', 'hearing aids?', 'sound processor', 'cochlear', 'contact lens(?:es)?',
  'thermometers?', 'blood pressure monitor', 'sphygmomanometer', 'pulse oximeter', 'oximeter', 'pregnancy test',
  'ovulation', 'self[- ]test(?:ing)?', 'home use', 'home test', 'lateral flow', 'wheelchairs?', 'mobility scooters?',
  'walking (?:aid|frame|stick)s?', 'rollators?', 'crutch(?:es)?', 'stair ?lifts?', 'commodes?', 'bath lifts?',
  'shower chairs?', 'ostomy', 'stoma', 'colostomy', 'ileostomy', 'urostomy', 'intermittent catheters?',
  'incontinence', 'breast pumps?', 'tens\b', 'oxygen concentrators?', 'home (?:dialysis|oxygen|ventilat\w*)',
  'peritoneal dialysis', 'defibrillators?', '\baed\b', 'condoms?', 'personal alarm', 'hospital bed for home',
].join('|') + String.raw`)`, 'i');

const HOSPITAL_ONLY = /\b(professional|hospital|surgical|surgery|theatre|x-?ray|mri\b|ct scanner|fluoroscop\w*|radiograph\w*|radiotherapy|endoscop\w*|anaesthe\w*|laborator\w*|analy[sz]er|stereotactic|apheresis|central venous|cardiac|catheter lab|implant\w*|ultrasound system|patient monitor)\b/i;

type FsnEntry = {
  manufacturer: string | null;
  device: string;
  heading: string;
  anchor: string | null;
  date: string | null;
  deviceType: string | null;
  model: string | null;
  ref: string | null;
  documentUrl: string | null;
};

/** Splits a weekly FSN list into its notices. */
function parseFsnList(html: string): FsnEntry[] {
  const out: FsnEntry[] = [];
  const parts = html.split(/<h3\b/i).slice(1);
  for (const part of parts) {
    const [headHtml, ...rest] = part.split(/<\/h3>/i);
    const anchor = headHtml.match(/id="([^"]+)"/)?.[1] ?? null;
    const heading = cleanText(headHtml.replace(/^[^>]*>/, '')) ?? '';
    if (!heading) continue;
    const body = rest.join(' ');
    const lines = [...body.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => ({ html: m[1], text: cleanText(m[1]) ?? '' }))
      .filter((l) => l.text);
    // "Manufacturer: Device" — split at the first colon only ("Tandem: t:slim X2 Insulin Pump").
    const split = heading.match(/^([^:]+?)\s*:\s*(.+)$/);
    const manufacturer = split ? split[1] : null;
    const device = split ? split[2] : heading;
    const dateLine = lines.find((l) => /^(\d{1,2}\s+)?(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4}$/i.test(l.text));
    const refLine = lines.find((l) => /MHRA reference/i.test(l.text));
    const modelLines = lines.filter((l) => /^(model|models|lot|lots|batch|serial|ref\b|reference\b|fmi\b|fsca\b)/i.test(l.text)).map((l) => l.text);
    const typeLine = lines.find((l) => l !== dateLine && l !== refLine && !modelLines.includes(l.text) && !/MHRA reference/i.test(l.text));
    out.push({
      manufacturer,
      device,
      heading,
      anchor,
      date: dateLine?.text ?? null,
      deviceType: typeLine?.text ?? null,
      model: modelLines.length ? modelLines.join('\n') : null,
      ref: refLine?.html.match(/>(\d{5,})</)?.[1] ?? refLine?.text.match(/(\d{4}\/\d{3}\/\d{3}\/\d{3}\/\d{3})/)?.[1] ?? null,
      documentUrl: refLine?.html.match(/href="([^"]+)"/)?.[1] ?? null,
    });
  }
  return out;
}

/** True for devices people use at home, rather than hospital equipment. */
function isHomeDevice(entry: Pick<FsnEntry, 'heading' | 'deviceType' | 'model'>): boolean {
  const text = [entry.heading, entry.deviceType, entry.model].filter(Boolean).join(' ');
  if (!HOME_DEVICE.test(text)) return false;
  if (/\bhome\b/i.test(text)) return true;
  return !HOSPITAL_ONLY.test(text);
}

const FSN_MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];

/** "14 October 2026" or "October 2026" → midday UTC on that day (the 1st when there's no day). */
function fsnDate(value: string | null, fallback: string): string {
  const m = value?.match(/^(?:(\d{1,2})\s+)?([A-Za-z]+)\s+(\d{4})$/);
  const month = m ? FSN_MONTHS.indexOf(m[2].toLowerCase()) : -1;
  if (!m || month < 0) return fallback;
  return new Date(Date.UTC(Number(m[3]), month, Number(m[1] ?? 1), 12)).toISOString();
}

/** Converts one notice from a weekly list into our Recall format. */
function normaliseFsn(entry: FsnEntry, pageUrl: string, pagePublished: string): Recall {
  const publishedAt = fsnDate(entry.date, pagePublished);
  const key = (entry.ref ?? entry.anchor ?? entry.heading).replace(/[^A-Za-z0-9]+/g, '-').slice(0, 60);
  const what = entry.deviceType ? ` (${entry.deviceType.replace(/\.$/, '')})` : '';
  return {
    id: `mhra-fsn:${key}`,
    source: 'mhra',
    sourceRef: entry.ref ?? key,
    alertType: 'field-safety-notice',
    title: entry.manufacturer ? `${entry.device} (${entry.manufacturer})` : entry.device,
    summary: shorten(`The manufacturer has issued a field safety notice for this device${what}. The notice explains the problem and what to do.`),
    advice: "Read the manufacturer's notice. If you use this device, contact the supplier, your pharmacist or the clinic that gave it to you. Don't stop using a device you rely on without advice.",
    riskLevel: null,
    categories: ['medicines'],
    allergens: [],
    businesses: entry.manufacturer ? [entry.manufacturer] : [],
    sourceUrl: entry.anchor ? `${pageUrl}#${entry.anchor}` : pageUrl,
    documentUrl: entry.documentUrl,
    imageUrl: null,
    publishedAt,
    updatedAt: publishedAt,
    products: [{
      name: entry.device,
      barcode: null,
      packSize: null,
      batchCodes: [],
      bestBefore: null,
      useBy: null,
      batchNotes: entry.model,
    }],
  };
}

/** Home-device notices from one weekly list (its GOV.UK content item). */
function homeFsnsFrom(content: Json): Recall[] {
  const pageUrl = `${GOVUK}${content.base_path ?? ''}`;
  const published = toIso(content.first_published_at ?? content.public_updated_at);
  return parseFsnList(content.details?.body ?? '').filter(isHomeDevice).map((e) => normaliseFsn(e, pageUrl, published));
}

/** Weekly FSN lists published since `since`, reduced to devices people use at home. */
async function fetchFsnSince(fetchFn: FetchFn, since: string, maxPages = 10): Promise<Recall[]> {
  const url = `${GOVUK}/api/search.json?filter_format=medical_safety_alert&filter_alert_type=${FSN_ALERT_TYPE}` +
    `&filter_public_timestamp=from:${since.slice(0, 10)}&order=-public_timestamp&count=${maxPages}&fields=link,public_timestamp`;
  const page = await getJson(fetchFn, url);
  const links = asArray<Json>(page.results).filter((r) => typeof r.link === 'string').map((r) => r.link as string);
  const contents = await mapLimit(links, 3, (link) => getJson(fetchFn, `${GOVUK}/api/content${link}`).catch(() => null));
  return contents.filter(Boolean).flatMap((c) => homeFsnsFrom(c));
}

// ───────── hse.ts ─────────
// Health and Safety Executive (HSE) safety alerts and notices: faults in work equipment, protective
// gear and processes. Published as a table at hse.gov.uk/safetybulletins/recent-bulletins.htm
// (Date MM/YYYY | Topic | Bulletin No | Industry), each linking to a page with "Issue",
// "Outline of the problem" and "Action required" sections.
//
// Many are for offshore, chemical or other specialist industries, which aren't relevant to the app's
// users. We keep the ones a tradesperson, small business, school or household might meet.
// Licence: Open Government Licence v3.0 — attribution required.

const HSE_BASE = 'https://www.hse.gov.uk/safetybulletins';

const SPECIALIST = /offshore|drilling|wind turbine|wind generation|marine|vessel|mooring|cargo|slop tank|radiograph|laborator|biological agent|nuclear|comah|refiner|mining|quarr|explosive|thermite|pesticide|oil and gas|gangway|grating|vapour recovery|motorsport|high voltage|switchgear|diving|pipeline|hydrogen sulphide|hydrogen sulfide/i;

type HseRow = { month: string; url: string; slug: string; topic: string; bulletin: string | null; audience: string | null };

/** Rows of the recent bulletins table. `month` is "YYYY-MM". */
function parseHseList(html: string): HseRow[] {
  const table = html.match(/<table[^>]*id="safetyalerts"[\s\S]*?<\/table>/i)?.[0] ?? html;
  const rows: HseRow[] = [];
  for (const row of table.matchAll(/<tr\b[\s\S]*?<\/tr>/gi)) {
    const cells = [...row[0].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((c) => c[1]);
    if (cells.length < 2) continue;
    const date = (cleanText(cells[0]) ?? '').match(/^(\d{1,2})\/(\d{4})$/);
    const link = cells[1].match(/href="([^"]+)"/)?.[1];
    if (!date || !link) continue;
    const url = link.startsWith('http') ? link : `${HSE_BASE}/${link.replace(/^\.?\//, '')}`;
    rows.push({
      month: `${date[2]}-${date[1].padStart(2, '0')}`,
      url,
      slug: (url.split('/').pop() ?? url).replace(/\.htm$/, ''),
      topic: cleanText(cells[1]) ?? '',
      bulletin: cleanText(cells[2]) || null,
      audience: cleanText(cells[3]) || null,
    });
  }
  return rows;
}

function isRelevantHse(row: Pick<HseRow, 'topic' | 'audience'>): boolean {
  return !SPECIALIST.test(`${row.topic} ${row.audience ?? ''}`);
}

const END_OF_CONTENT = /^(guidance|relevant legal|further information|further guidance|related|is this page useful|footer|references?)/i;

/**
 * The text after a heading such as "Issue" or "Action required". With `throughSubheadings`, it carries
 * on past sub-headings ("Users should:", "Check", ...) until the guidance and references at the end.
 */
function sectionAfter(html: string, heading: RegExp, throughSubheadings = false): string | null {
  const parts = html.split(/(<h[1-4][^>]*>[\s\S]*?<\/h[1-4]>)/i);
  for (let i = 1; i < parts.length; i += 2) {
    if (!heading.test(cleanText(parts[i]) ?? '')) continue;
    const pieces: string[] = [cleanText(parts[i + 1] ?? '') ?? ''];
    if (throughSubheadings) {
      for (let j = i + 2; j < parts.length; j += 2) {
        const h = cleanText(parts[j]) ?? '';
        if (END_OF_CONTENT.test(h)) break;
        pieces.push(h, cleanText(parts[j + 1] ?? '') ?? '');
      }
    }
    const text = pieces.filter(Boolean).join('\n').trim();
    if (text) return text;
  }
  return null;
}

function normaliseHse(row: HseRow, html: string | null): Recall {
  const page = html ?? '';
  const main = page.match(/id="page-contents"[\s\S]*$/i)?.[0] ?? page;
  const kind = /safety alert/i.test(main.slice(0, 3000)) ? 'Safety alert' : 'Safety notice';
  const issueDate = cleanText(main.match(/Issue date:\s*([^<]+)/i)?.[1] ?? '')?.match(/(\d{1,2})\/(\d{2,4})/);
  const month = issueDate ? `${issueDate[2].length === 2 ? `20${issueDate[2]}` : issueDate[2]}-${issueDate[1].padStart(2, '0')}` : row.month;
  const publishedAt = new Date(`${month}-01T09:00:00Z`).toISOString();
  const issue = sectionAfter(main, /^issue$/i) ?? sectionAfter(main, /outline of the problem/i);
  const action = sectionAfter(main, /action required/i, true);
  return {
    id: `hse:${(row.bulletin ?? row.slug).replace(/[^A-Za-z0-9-]+/g, '-')}`,
    source: 'hse',
    sourceRef: row.bulletin ?? row.slug,
    alertType: 'safety-alert',
    title: row.topic,
    summary: shorten(issue ? `${kind}: ${issue}` : `${kind} from the Health and Safety Executive.`),
    advice: shorten(action, 400),
    riskLevel: kind === 'Safety alert' ? 'serious' : null,
    categories: ['trades-tools'],
    allergens: [],
    businesses: [],
    sourceUrl: row.url,
    documentUrl: null,
    imageUrl: null,
    publishedAt,
    updatedAt: publishedAt,
    products: [{
      name: row.topic, barcode: null, packSize: null, batchCodes: [], bestBefore: null, useBy: null,
      batchNotes: row.audience ? `Who it's for: ${row.audience}` : null,
    }],
  };
}

/** Relevant HSE alerts and notices from the month of `since` onwards. */
async function fetchHseSince(fetchFn: FetchFn, since: string, maxItems = 20): Promise<Recall[]> {
  const fromMonth = since.slice(0, 7);
  const rows = parseHseList(await getText(fetchFn, `${HSE_BASE}/recent-bulletins.htm`))
    .filter((r) => r.month >= fromMonth && isRelevantHse(r))
    .slice(0, maxItems);
  const pages = await mapLimit(rows, 3, (r) => getText(fetchFn, r.url).catch(() => null));
  return rows.map((r, i) => normaliseHse(r, pages[i]));
}

// ───────── eu.ts ─────────
// EU Safety Gate: dangerous non-food products reported by EU countries, published every Friday as an
// XML weekly report. Many of these products are sold online in the UK too, so the app shows them as
// "EU warnings", clearly separate from UK recalls. They only trigger alerts for barcode or cupboard
// matches, never for categories.
// Weekly report list: https://ec.europa.eu/safety-gate-alerts/api/download/weeklyReport/list/xml/en
// Licence: the weekly reports are published as open data (CC0 on data.europa.eu); credit the
// European Commission's Safety Gate.

const EU_LIST = 'https://ec.europa.eu/safety-gate-alerts/api/download/weeklyReport/list/xml/en';

// Asked for compressed, the EU server sends its files without a length and just hangs up at the end,
// which the Supabase runtime reports as "error reading a body from connection". Uncompressed, it sends
// them in marked chunks with a clear end, which reads cleanly everywhere. And if the connection still
// drops after the closing tag has arrived, we already have the whole file, so we keep it.
const EU_GET = {
  headers: { 'Accept-Encoding': 'identity' },
  complete: (text: string) => /<\/Safety-Gate>\s*$/.test(text),
};

/** Product types we leave out: vehicles are handled by national schemes, not useful here. */
const SKIP_CATEGORIES = /motor vehicles|recreational craft/i;

type EuReport = { reference: string; date: string; url: string };

function tag(xml: string, name: string): string | null {
  const m = xml.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`));
  if (!m) return null;
  const value = m[1].replace(/^<!\[CDATA\[([\s\S]*?)\]\]>$/, '$1').trim();
  return decode(value) || null;
}

function decode(s: string): string {
  return s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;|&#39;/g, "'");
}

const REPORT_ENTRY = /<weeklyReport>([\s\S]*?)<\/weeklyReport>/g;

function reportFrom(entry: string): EuReport | null {
  const y = tag(entry, 'year'), mo = tag(entry, 'month'), d = tag(entry, 'day');
  const url = tag(entry, 'URL');
  if (!y || !mo || !d || !url) return null;
  return { reference: tag(entry, 'reference') ?? `${y}-${mo}-${d}`, date: `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`, url };
}

/** All weekly reports, oldest first. */
function parseEuReportList(xml: string): EuReport[] {
  return [...xml.matchAll(REPORT_ENTRY)]
    .map((m) => reportFrom(m[1]))
    .filter((r): r is EuReport => r !== null)
    .sort((a, b) => a.date.localeCompare(b.date));
}

/**
 * The full list goes back to 2005 and is newest first, so we only read its top: up to the second
 * report older than `cutoff` (two, in case one report has a misprinted date).
 */
function listReaches(cutoff: string): (text: string) => boolean {
  return (text) => {
    let older = 0;
    for (const m of text.matchAll(REPORT_ENTRY)) {
      const r = reportFrom(m[1]);
      if (r && r.date < cutoff && ++older >= 2) return true;
    }
    return false;
  };
}

/** How far back the list is read: a little more than the two years of history the backfill loads. */
const LIST_DAYS = 760;
const LIST_FRESH_MS = 15 * 60_000;
const listCache = new WeakMap<FetchFn, { at: number; readTo: string; reports: EuReport[] }>();

/**
 * Weekly reports dated `cutoff` or later, oldest first. The list is read once per run and shared
 * by the everyday check and the history loader.
 */
async function euReportsSince(fetchFn: FetchFn, cutoff: string, now = Date.now()): Promise<EuReport[]> {
  let cached = listCache.get(fetchFn);
  if (!cached || now - cached.at > LIST_FRESH_MS || cached.readTo > cutoff) {
    const depth = new Date(now - LIST_DAYS * 86400_000).toISOString().slice(0, 10);
    const readTo = cutoff < depth ? cutoff : depth;
    const reports = parseEuReportList(await getTextUntil(fetchFn, EU_LIST, listReaches(readTo), EU_GET));
    cached = { at: now, readTo, reports };
    listCache.set(fetchFn, cached);
  }
  return cached.reports.filter((r) => r.date >= cutoff);
}

/** "Category of measure(s): Recall of the product from end users" → "Recall of the product from end users". */
function euMeasures(text: string | null): string[] {
  if (!text) return [];
  return [...new Set([...text.matchAll(/Category of measure\(s\):\s*(.*?)(?=Date of entry into force:|Type of economic operator|$)/gs)]
    .map((m) => m[1].trim()).filter(Boolean))];
}

function euCategories(category: string, text: string) {
  const slug = category.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return categoriesForOpss(slug, text);
}

/** Converts one notification from a weekly report. Returns null for ones we leave out. */
function normaliseEuNotification(xml: string, reportDate: string): Recall | null {
  const category = tag(xml, 'category') ?? '';
  if (SKIP_CATEGORIES.test(category)) return null;
  if ((tag(xml, 'type') ?? 'Consumer') !== 'Consumer') return null;
  const caseNumber = tag(xml, 'caseNumber');
  const reference = tag(xml, 'reference');
  if (!caseNumber || !reference) return null;
  const product = tag(xml, 'product') ?? category;
  const brand = tag(xml, 'brand');
  const name = tag(xml, 'name');
  const model = tag(xml, 'type_numberOfModel');
  const barcodes = (tag(xml, 'barcode') ?? '').split(/[,;\s/]+/).map((b) => b.replace(/\D/g, '')).filter((b) => b.length >= 8 && b.length <= 14);
  const batch = (tag(xml, 'batchNumber') ?? '').split(/[,;]+/).map((b) => b.trim()).filter(Boolean);
  const risk = tag(xml, 'riskType');
  const danger = tag(xml, 'danger');
  const level = tag(xml, 'level');
  const country = tag(xml, 'notifyingCountry');
  const measures = euMeasures(tag(xml, 'measures'));
  const pictures = [...xml.matchAll(/<picture>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/picture>/g)].map((m) => m[1].trim());
  const sold = tag(xml, 'onlineTrader');
  const title = [brand, name && name !== product ? name : null].filter(Boolean).join(' ') || product;
  const publishedAt = new Date(`${reportDate}T12:00:00Z`).toISOString();
  const text = [category, product, name, tag(xml, 'description')].filter(Boolean).join(' ');

  const intro = `Reported as dangerous in the EU${country ? ` by ${country}` : ''}${risk ? ` (${risk.toLowerCase()})` : ''}.`;
  const advice = [
    measures.length ? `Action taken in the EU: ${measures.join('; ')}.` : null,
    "If you have this product, stop using it and contact the seller. It may also have been sold in the UK, especially online.",
  ].filter(Boolean).join(' ');

  return {
    id: `eu:${caseNumber.replace(/[^A-Za-z0-9]+/g, '-')}`,
    source: 'eu',
    sourceRef: caseNumber,
    alertType: 'eu-warning',
    title: product !== title && !title.toLowerCase().includes(product.toLowerCase()) ? `${title} (${product.toLowerCase()})` : title,
    summary: shorten(`${intro} ${danger ?? ''}`.trim()),
    advice: shorten(advice, 400),
    riskLevel: /serious/i.test(level ?? '') ? 'serious' : /high/i.test(level ?? '') ? 'high' : /medium/i.test(level ?? '') ? 'medium' : /low/i.test(level ?? '') ? 'low' : null,
    categories: euCategories(category, text),
    allergens: [],
    businesses: [brand, sold && !/^other/i.test(sold) ? sold.replace(/\s*\/\s*$/, '') : null].filter((b): b is string => !!b),
    sourceUrl: reference,
    documentUrl: null,
    imageUrl: pictures[0] ?? null,
    publishedAt,
    updatedAt: publishedAt,
    products: [{
      name: [brand, name ?? product].filter(Boolean).join(' '),
      barcode: barcodes[0] ?? null,
      packSize: null,
      batchCodes: batch,
      bestBefore: null,
      useBy: null,
      batchNotes: [model ? `Model: ${model}` : null, barcodes.length > 1 ? `Barcodes: ${barcodes.join(', ')}` : null].filter(Boolean).join('\n') || null,
    }],
  };
}

function parseEuReport(xml: string, reportDate: string): Recall[] {
  return [...xml.matchAll(/<notifications\b[\s\S]*?<\/notifications>/g)]
    .map((m) => normaliseEuNotification(m[0], reportDate))
    .filter((r): r is Recall => r !== null);
}

/**
 * Downloads weekly reports (oldest first), two at a time. If one fails, the batch stops just before it,
 * so it's tried again next run rather than skipped; if the first one fails, this throws.
 * A report the server says doesn't exist (404 and the like) is passed over.
 */
async function fetchEuReports(fetchFn: FetchFn, reports: EuReport[]): Promise<{ recalls: Recall[]; fetched: number }> {
  const results = await mapLimit(reports, 2, (r) =>
    getText(fetchFn, r.url, EU_GET).then((xml) => ({ xml }), (error: unknown) => (isPermanent(error) ? { xml: '' } : { error })));
  const failed = results.findIndex((r) => 'error' in r);
  if (failed === 0) throw (results[0] as { error: unknown }).error;
  const fetched = failed < 0 ? reports.length : failed;
  const recalls = reports.slice(0, fetched).flatMap((r, i) => parseEuReport((results[i] as { xml: string }).xml, r.date));
  return { recalls, fetched };
}

/** Weekly reports published since `since` (at most `maxReports`, newest). */
async function fetchEuSince(fetchFn: FetchFn, since: string, maxReports = 6): Promise<Recall[]> {
  const reports = (await euReportsSince(fetchFn, since.slice(0, 10))).slice(-maxReports);
  return (await fetchEuReports(fetchFn, reports)).recalls;
}

// ───────── backfill.ts ─────────
// Loads older recalls (two years) from each source, a batch at a time, oldest first.
// It runs inside collect-recalls after the usual collection, so the library fills up over a day or two
// without slowing anything down. Backfilled recalls are saved but never trigger alerts.
//
// Each source keeps its place in the backfill_state table: the date it started from and how many
// items it has worked through. Newer items only ever appear at the end of the list, so the count stays valid.

const BACKFILL_DAYS = 730;

type BackfillState = { key: string; fromDate: string; offset: number; done: boolean };
type BackfillBatch = { recalls: Recall[]; scanned: number; done: boolean };

type Step = (fetchFn: FetchFn, fromDate: string, offset: number) => Promise<BackfillBatch>;

/** A GOV.UK finder, read oldest first from `fromDate`, `batch` items at a time. */
function govuk(filter: string, batch: number, convert: (content: Json) => Recall[], keep: (r: Json) => boolean = () => true): Step {
  return async (fetchFn, fromDate, offset) => {
    const url = `${GOVUK}/api/search.json?${filter}&filter_public_timestamp=from:${fromDate}` +
      `&order=public_timestamp&count=${batch}&start=${offset}&fields=link,public_timestamp,title`;
    const page = await getJson(fetchFn, url);
    const results = asArray<Json>(page.results);
    const links = results.filter((r) => typeof r.link === 'string' && keep(r)).map((r) => r.link as string);
    const contents = await mapLimit(links, 4, (link) => getJson(fetchFn, `${GOVUK}/api/content${link}`).catch(() => null));
    const recalls = contents
      .filter((c): c is Json => !!c && !(c.withdrawn_notice && Object.keys(c.withdrawn_notice).length))
      .flatMap((c) => { try { return convert(c); } catch { return []; } });
    return { recalls, scanned: results.length, done: results.length < batch };
  };
}

const fsaStep: Step = async (fetchFn, fromDate, offset) => {
  const batch = 40;
  const list = await getJson(fetchFn, `${FSA_BASE}?since=${encodeURIComponent(`${fromDate}T00:00:00Z`)}&_sort=created&_limit=${batch}&_offset=${offset}`);
  const items = asArray<Json>(list.items);
  return { recalls: await fsaRecallsFor(fetchFn, items), scanned: items.length, done: items.length < batch };
};

/** EU Safety Gate: two weekly reports at a time. A report that fails is tried again next run. */
const euStep: Step = async (fetchFn, fromDate, offset) => {
  const reports = await euReportsSince(fetchFn, fromDate);
  const { recalls, fetched } = await fetchEuReports(fetchFn, reports.slice(offset, offset + 2));
  return { recalls, scanned: fetched, done: offset + fetched >= reports.length };
};

const BACKFILL_STEPS: Record<string, Step> = {
  fsa: fsaStep,
  opss: govuk('filter_format=product_safety_alert_report_recall', 40, (c) => [normaliseOpssItem(c)]),
  'mhra-recalls': govuk('filter_format=medical_safety_alert&filter_alert_type=medicines-recall-notification', 40, (c) => [normaliseMhraItem(c)]),
  'mhra-devices': govuk('filter_format=medical_safety_alert&filter_alert_type=device-safety-information', 40, (c) => [normaliseMhraItem(c)]),
  'mhra-fsn': govuk(`filter_format=medical_safety_alert&filter_alert_type=${FSN_ALERT_TYPE}`, 6, homeFsnsFrom),
  vmd: govuk('filter_organisations=veterinary-medicines-directorate&filter_content_store_document_type=news_story', 40,
    (c) => (isVmdRecallTitle(String(c.title ?? '')) ? [normaliseVmdItem(c)] : []),
    (r) => isVmdRecallTitle(String(r.title ?? ''))),
  eu: euStep,
};

function backfillStartDate(now = new Date()): string {
  return new Date(now.getTime() - BACKFILL_DAYS * 86400_000).toISOString().slice(0, 10);
}

/**
 * Runs one batch for each source that isn't finished, while time allows.
 * `save` stores recalls (without alerts); `load`/`store` read and write each source's place.
 */
async function runBackfill(opts: {
  fetchFn: FetchFn;
  load: () => Promise<BackfillState[]>;
  store: (state: BackfillState) => Promise<void>;
  save: (recalls: Recall[]) => Promise<void>;
  deadline: number; // ms timestamp: start no new batch after this
  now?: Date;
}): Promise<Record<string, { saved: number; offset: number; done: boolean; error?: string }>> {
  const report: Record<string, { saved: number; offset: number; done: boolean; error?: string }> = {};
  const states = new Map((await opts.load()).map((s) => [s.key, s]));
  for (const [key, step] of Object.entries(BACKFILL_STEPS)) {
    const state = states.get(key) ?? { key, fromDate: backfillStartDate(opts.now), offset: 0, done: false };
    if (state.done) continue;
    if (Date.now() > opts.deadline) break;
    try {
      const batch = await step(opts.fetchFn, state.fromDate, state.offset);
      if (batch.recalls.length) await opts.save(batch.recalls);
      const next = { ...state, offset: state.offset + batch.scanned, done: batch.done };
      await opts.store(next);
      report[key] = { saved: batch.recalls.length, offset: next.offset, done: next.done };
    } catch (err) {
      report[key] = { saved: 0, offset: state.offset, done: false, error: err instanceof Error ? err.message : String(err) };
    }
  }
  return report;
}

// ───────── matching.ts ─────────
// Decides who should hear about a recall, and how sure we are.
//
// Priority (one alert per person per recall):
//   1. cupboard  – something they told us they own looks like the recalled product
//   2. allergen  – an allergy alert for an allergen in their household
//   3. category  – a recall in a category they follow
//
// Cupboard confidence:
//   barcode  – exact barcode match (only when the agency publishes barcodes)
//   likely   – brand matches and most of the product name matches
//   possible – partial match; the app asks the person to check the batch code
// We never claim certainty from a name match: the person always confirms.

const STOPWORDS = new Set([
  'the', 'and', 'with', 'for', 'from', 'of', 'in', 'a', 'an', 'to', 'by', 'on',
  'pack', 'packs', 'multipack', 'x', 'g', 'kg', 'ml', 'l', 'ltr', 'litre', 'litres',
  'recalls', 'recall', 'because', 'may', 'contain', 'contains', 'undeclared', 'product', 'products',
  'sold', 'via', 'amazon', 'ebay', 'temu', 'shein', 'online', 'presenting', 'serious', 'risk',
]);

/** Meaningful lower-case words, lightly de-pluralised. "Baby Rice Cereals 200g" -> baby, rice, cereal, 200g */
function tokens(text: string | null | undefined): string[] {
  if (!text) return [];
  return text
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/(\d)\s+(g|kg|ml|l|ltr)\b/g, '$1$2') // "200 g" -> "200g"
    .split(/[^a-z0-9]+/)
    .filter((w) => w && !STOPWORDS.has(w) && !/^\d{1,2}$/.test(w) && (w.length >= 3 || /\d/.test(w)))
    .map((w) => (w.length > 3 && w.endsWith('s') && !/(ss|us|is)$/.test(w) ? w.slice(0, -1) : w));
}

function barcodesMatch(a: string | null, b: string | null): boolean {
  if (!a || !b) return false;
  // Treat EAN-13 and UPC-A (12 digits) as the same code when they differ only by a leading zero.
  const clean = (s: string) => s.replace(/\D/g, '').replace(/^0+/, '');
  return clean(a).length >= 8 && clean(a) === clean(b);
}

/** How well one cupboard item matches one recall. */
function cupboardConfidence(item: CupboardItem, recall: Recall): MatchConfidence {
  if (item.dismissedRecalls.includes(recall.id)) return null;

  if (item.barcode && recall.products.some((p) => barcodesMatch(item.barcode, p.barcode))) {
    return 'barcode';
  }

  const recallWords = new Set(tokens([
    recall.title,
    ...recall.products.map((p) => p.name),
    ...recall.businesses,
  ].join(' ')));

  const nameWords = tokens(item.name);
  if (nameWords.length === 0) return null;
  const overlap = nameWords.filter((w) => recallWords.has(w)).length / nameWords.length;

  const brandWords = tokens(item.brand);
  const brandKnown = brandWords.length > 0;
  const brandMatches = brandKnown && brandWords.every((w) => recallWords.has(w));

  if (brandKnown && !brandMatches) return null; // different brand: not this recall
  if (brandMatches && overlap >= 0.75) return 'likely';
  if (brandMatches && overlap >= 0.5) return 'possible';
  if (!brandKnown && nameWords.length >= 2 && overlap >= 0.75) return 'possible';
  return null;
}

const RANK: Record<string, number> = { barcode: 3, likely: 2, possible: 1 };

/**
 * Works out every alert a recall should create.
 * `profiles` and `cupboard` may be pre-filtered by the database; this function
 * makes the final decision either way.
 */
function matchRecall(recall: Recall, profiles: UserProfile[], cupboard: CupboardItem[]): Match[] {
  const byUser = new Map<string, Match>();

  // 1. Cupboard matches — keep the most confident item per person.
  for (const item of cupboard) {
    const confidence = cupboardConfidence(item, recall);
    if (!confidence) continue;
    const existing = byUser.get(item.userId);
    if (!existing || RANK[confidence] > RANK[existing.confidence ?? '']) {
      byUser.set(item.userId, { userId: item.userId, recallId: recall.id, reason: 'cupboard', confidence, cupboardItemId: item.id });
    }
  }

  // EU warnings aren't UK recalls, so they only alert people whose cupboard matches.
  for (const profile of recall.source === 'eu' ? [] : profiles) {
    if (byUser.has(profile.userId)) continue;

    // 2. Allergens in their household: the 14 UK allergens, or ones they typed themselves.
    if (recall.allergens.some((a) => profile.allergens.includes(a))
      || profile.allergens.some((a) => mentionsOtherAllergen(recall, a))) {
      byUser.set(profile.userId, { userId: profile.userId, recallId: recall.id, reason: 'allergen', confidence: null, cupboardItemId: null });
      continue;
    }

    // 3. Categories they follow.
    if (recall.categories.some((c) => profile.categories.includes(c))) {
      byUser.set(profile.userId, { userId: profile.userId, recallId: recall.id, reason: 'category', confidence: null, cupboardItemId: null });
    }
  }

  return [...byUser.values()];
}

// Allergens people type themselves ("kiwi", "pea protein") arrive as "other:kiwi" beside the
// 14 keys. Keep in step with mentionsOtherAllergen in the app's src/logic.js.
const OTHER_ALLERGEN = 'other:';

/** Whether a food recall mentions an allergen someone typed themselves, as a whole word. */
function mentionsOtherAllergen(recall: Recall, key: string): boolean {
  if (!key.startsWith(OTHER_ALLERGEN)) return false;
  const word = key.slice(OTHER_ALLERGEN.length).trim();
  if (word.length < 2) return false;
  const food = recall.alertType === 'allergy' || recall.categories.includes('food-drink');
  if (!food) return false;
  const text = [recall.title, recall.summary, ...recall.products.map((p) => p.name)].join(' ').toLowerCase();
  const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`(^|[^a-z])${escaped}(s|es)?([^a-z]|$)`).test(text);
}

/** The words on someone's lock screen. Short, calm and specific. */
function notificationText(recall: Recall, match: Match, itemName?: string): { title: string; body: string } {
  if (match.reason === 'cupboard') {
    const what = itemName ?? recall.title;
    if (recall.source === 'eu') {
      return match.confidence === 'barcode'
        ? { title: 'Safety warning: an item in your cupboard', body: `${what} was reported as dangerous in the EU. Tap to see what to do.` }
        : { title: 'Possible safety warning in your cupboard', body: `${what} may match a product reported as dangerous in the EU. Tap to check.` };
    }
    return match.confidence === 'barcode'
      ? { title: 'Recall: an item in your cupboard', body: `${what} has been recalled. Tap to see what to do.` }
      : { title: 'Possible recall in your cupboard', body: `${what} may be affected. Tap to check your batch code.` };
  }
  if (match.reason === 'allergen') {
    return { title: 'Allergy alert', body: recall.title };
  }
  if (recall.alertType === 'field-safety-notice') return { title: 'Medical device notice', body: recall.title };
  if (recall.source === 'hse') return { title: 'Work safety alert', body: recall.title };
  return { title: recall.riskLevel === 'serious' ? 'Serious-risk recall' : 'New recall', body: recall.title };
}

// ───────── push.ts ─────────
// Sends phone notifications through Expo's push service, which delivers to
// both Apple (APNs) and Android (FCM) from one request. Free to use.
// Docs: https://docs.expo.dev/push-notifications/sending-notifications/

interface PushMessage {
  to: string;           // Expo push token
  title: string;
  body: string;
  data?: Record<string, unknown>;
  sound?: 'default' | null;
  priority?: 'default' | 'high';
}

const EXPO_PUSH_URL = 'https://exp.host/--/api/v2/push/send';
const BATCH = 100; // Expo's limit per request

/**
 * Sends messages and returns tokens Expo says are dead (app uninstalled),
 * so the caller can delete them. A batch that fails is reported in `errors`
 * rather than stopping everyone else's alerts.
 */
async function sendPush(fetchFn: FetchFn, messages: PushMessage[], accessToken?: string): Promise<{ sent: number; deadTokens: string[]; errors: string[] }> {
  const result = { sent: 0, deadTokens: [] as string[], errors: [] as string[] };
  for (let i = 0; i < messages.length; i += BATCH) {
    await sendBatch(fetchFn, messages.slice(i, i + BATCH), accessToken, result, true);
  }
  return result;
}

async function sendBatch(
  fetchFn: FetchFn,
  batch: PushMessage[],
  accessToken: string | undefined,
  result: { sent: number; deadTokens: string[]; errors: string[] },
  maySplit: boolean,
): Promise<void> {
  let res: Response;
  try {
    res = await fetchFn(EXPO_PUSH_URL, {
      method: 'POST',
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json',
        ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
      },
      body: JSON.stringify(batch.map((m) => ({ sound: 'default', priority: 'high', ...m }))),
    });
  } catch (e) {
    result.errors.push(`Expo push unreachable: ${(e as Error).message}`);
    return;
  }
  const text = await res.text();
  let json: Json = null;
  try { json = JSON.parse(text); } catch { /* not JSON */ }

  if (!res.ok) {
    // Expo refuses a batch that mixes tokens from different apps (for example an Expo Go
    // preview and the real app). It tells us which token belongs to which app, so send
    // each app's share on its own.
    const mixed = (json?.errors ?? []).find((e: Json) => e?.code === 'PUSH_TOO_MANY_EXPERIENCE_IDS');
    if (maySplit && mixed?.details && typeof mixed.details === 'object') {
      const groups = new Map<string, PushMessage[]>();
      const owner = new Map<string, string>();
      for (const [project, tokens] of Object.entries(mixed.details as Record<string, string[]>)) {
        for (const token of tokens ?? []) owner.set(token, project);
      }
      for (const m of batch) {
        const key = owner.get(m.to) ?? '';
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key)!.push(m);
      }
      for (const group of groups.values()) await sendBatch(fetchFn, group, accessToken, result, false);
      return;
    }
    result.errors.push(`Expo push failed: ${res.status} ${text.slice(0, 300)}`);
    return;
  }

  const tickets: Json[] = json?.data ?? [];
  tickets.forEach((ticket, idx) => {
    if (ticket?.status === 'ok') result.sent++;
    else if (ticket?.details?.error === 'DeviceNotRegistered') result.deadTokens.push(batch[idx].to);
  });
}

// ───────── images.ts ─────────
// Product photos. The FSA and OPSS publish their photos inside a PDF attached to each
// notice, not as normal images. Photos in PDFs are almost always stored as plain JPEG
// data, so we can lift the biggest one out without rendering the PDF.

const enc = new TextEncoder();
const STREAM = enc.encode('stream');
const ENDSTREAM = enc.encode('endstream');

function indexOf(hay: Uint8Array, needle: Uint8Array, from = 0): number {
  const first = needle[0];
  const last = hay.length - needle.length;
  for (let i = from; i <= last; i++) {
    if (hay[i] !== first) continue;
    let j = 1;
    while (j < needle.length && hay[i + j] === needle[j]) j++;
    if (j === needle.length) return i;
  }
  return -1;
}

function ascii(bytes: Uint8Array, start: number, end: number): string {
  let s = '';
  for (let i = Math.max(0, start); i < end; i++) s += String.fromCharCode(bytes[i]);
  return s;
}

interface PdfImage {
  jpeg: Uint8Array;
  width: number;
  height: number;
}

/**
 * Finds every JPEG photo stored in a PDF. Skips images that aren't plain JPEG (for example
 * compressed twice), CMYK images (they show up with wrong colours in phones), and tiny ones.
 */
function jpegsInPdf(pdf: Uint8Array, minSide = 120): PdfImage[] {
  const found: PdfImage[] = [];
  let pos = 0;
  while (pos < pdf.length) {
    const s = indexOf(pdf, STREAM, pos);
    if (s < 0) break;
    // Skip "endstream", which also contains "stream".
    const isEnd = s >= 3 && ascii(pdf, s - 3, s) === 'end';
    let dataStart = s + STREAM.length;
    if (pdf[dataStart] === 0x0d) dataStart++;
    if (pdf[dataStart] === 0x0a) dataStart++;
    pos = s + STREAM.length;
    if (isEnd) continue;

    // The stream's description sits just before the word "stream".
    const dict = ascii(pdf, s - 1500, s);
    const dictStart = dict.lastIndexOf('<<');
    const header = dictStart >= 0 ? dict.slice(dictStart) : dict;
    if (!/\/Subtype\s*\/Image/.test(header) || !/\/DCTDecode/.test(header)) continue;
    if (/\/FlateDecode/.test(header) || /\/DeviceCMYK/.test(header)) continue;
    if (pdf[dataStart] !== 0xff || pdf[dataStart + 1] !== 0xd8) continue;

    const e = indexOf(pdf, ENDSTREAM, dataStart);
    if (e < 0) break;
    // The JPEG ends at its last FF D9 marker before "endstream".
    let end = -1;
    for (let i = e - 1; i > dataStart + 1 && i > e - 16; i--) {
      if (pdf[i - 1] === 0xff && pdf[i] === 0xd9) { end = i + 1; break; }
    }
    pos = e + ENDSTREAM.length;
    if (end < 0) continue;

    const width = Number(header.match(/\/Width\s+(\d+)/)?.[1] ?? 0);
    const height = Number(header.match(/\/Height\s+(\d+)/)?.[1] ?? 0);
    if (width && height && Math.min(width, height) < minSide) continue;
    found.push({ jpeg: pdf.slice(dataStart, end), width, height });
  }
  return found;
}

/** The biggest photo in the PDF: product photos are larger than logos and icons. */
function bestPhoto(pdf: Uint8Array): PdfImage | null {
  const all = jpegsInPdf(pdf);
  if (!all.length) return null;
  return all.reduce((a, b) => (b.width * b.height || b.jpeg.length) > (a.width * a.height || a.jpeg.length) ? b : a);
}

const MAX_PDF_BYTES = 10 * 1024 * 1024;

async function downloadPdf(fetchFn: FetchFn, url: string): Promise<Uint8Array | null> {
  const res = await fetchFn(url, { headers: { 'User-Agent': 'HeadsUpHome/1.0 (recall alerts)' } });
  if (!res.ok) return null;
  const size = Number(res.headers.get('content-length') ?? 0);
  if (size > MAX_PDF_BYTES) return null;
  const bytes = new Uint8Array(await res.arrayBuffer());
  if (bytes.length > MAX_PDF_BYTES || ascii(bytes, 0, 5) !== '%PDF-') return null;
  return bytes;
}

/** A safe file name for a recall id like "fsa:FSA-PRIN-45-2026". */
const imagePath = (recallId: string) => `${recallId.replace(/[^A-Za-z0-9-]+/g, '_')}.jpg`;

// ───────── collect-recalls/index.ts ─────────
// collect-recalls: the engine. Runs every hour (see migrations/0002_schedule.sql).
//
// 1. Asks every source (FSA, FSS, OPSS, MHRA, VMD, HSE, EU Safety Gate) for anything new since last run
// 2. Saves it in our own format
// 3. Works out who should be told (cupboard, allergens, categories)
// 4. Sends phone notifications (category alerts wait for the daily digest if the person chose that)

const PHOTOS_PER_RUN = 25; // the rest are picked up on later hourly runs
const PHOTO_BUCKET = 'recall-images';

/**
 * Finds recalls that have a notice PDF but no photo yet, pulls the product photo out of
 * the PDF, and stores it in Supabase Storage. Each recall is tried once, so a PDF without
 * a usable photo isn't downloaded every hour.
 */
async function addPhotos(db: Db): Promise<{ added: number; checked: number }> {
  const { data: todo, error } = await db
    .from('recalls')
    .select('id, document_url')
    .is('image_url', null)
    .is('image_checked_at', null)
    .not('document_url', 'is', null)
    .order('published_at', { ascending: false })
    .limit(PHOTOS_PER_RUN);
  if (error) throw error;

  const results = await mapLimit(todo ?? [], 3, async (row: { id: string; document_url: string }) => {
    let imageUrl: string | null = null;
    try {
      const pdf = await downloadPdf(fetch, row.document_url);
      const photo = pdf ? bestPhoto(pdf) : null;
      if (photo) {
        const path = imagePath(row.id);
        const { error: upErr } = await db.storage.from(PHOTO_BUCKET).upload(path, photo.jpeg, { contentType: 'image/jpeg', upsert: true });
        if (!upErr) imageUrl = db.storage.from(PHOTO_BUCKET).getPublicUrl(path).data.publicUrl;
      }
    } catch {
      // A broken or unusual PDF just means no photo for this recall.
    }
    await db.from('recalls').update({ image_url: imageUrl, image_checked_at: new Date().toISOString() }).eq('id', row.id);
    return imageUrl ? 1 : 0;
  });
  return { added: results.reduce((a: number, b: number) => a + b, 0), checked: results.length };
}

const FIRST_RUN_DAYS = 30; // history to load the very first time, so the app isn't empty at launch
// Pet medicine recalls are rare (a handful a year) and the VMD withdraws each notice once its recall
// is over, so a year of history gives just the recalls that still apply.
// HSE publishes only a few alerts a year, so it starts with two years.
const FIRST_RUN_DAYS_BY_SOURCE: Record<string, number> = { vmd: 365, hse: 730 };
// Older recalls are loaded separately, a batch each run (see backfill.ts). This is how long the
// backfill may keep starting new batches, so the whole run stays well inside its time limit.
const BACKFILL_SECONDS = 55;
/** Shown in each run's report, so we can tell which version of the engine ran. */
const ENGINE_VERSION = '2026-11-08.1';

type Db = SupabaseClient;

function recallRow(r: Recall) {
  return {
    id: r.id, source: r.source, source_ref: r.sourceRef, alert_type: r.alertType,
    title: r.title, summary: r.summary, advice: r.advice, risk_level: r.riskLevel,
    categories: r.categories, allergens: r.allergens, businesses: r.businesses,
    source_url: r.sourceUrl, document_url: r.documentUrl, published_at: r.publishedAt, updated_at: r.updatedAt,
  };
}

async function saveRecalls(db: Db, recalls: Recall[]): Promise<Recall[]> {
  if (recalls.length === 0) return [];
  const ids = recalls.map((r) => r.id);
  const { data: existing, error: readErr } = await db.from('recalls').select('id').in('id', ids);
  if (readErr) throw readErr;
  const known = new Set((existing ?? []).map((e: { id: string }) => e.id));

  // image_url is only written when the source gives a photo, so one we've already extracted from a
  // PDF is never wiped. The two groups go separately because an upsert writes the same columns for every row.
  const checkedAt = new Date().toISOString();
  const withPhoto = recalls.filter((r) => r.imageUrl).map((r) => ({ ...recallRow(r), image_url: r.imageUrl, image_checked_at: checkedAt }));
  const withoutPhoto = recalls.filter((r) => !r.imageUrl).map(recallRow);
  for (const rows of [withPhoto, withoutPhoto]) {
    if (!rows.length) continue;
    const { error: upsertErr } = await db.from('recalls').upsert(rows);
    if (upsertErr) throw upsertErr;
  }

  // Products are replaced wholesale: agencies sometimes add batches to an existing notice.
  const { error: delErr } = await db.from('recall_products').delete().in('recall_id', ids);
  if (delErr) throw delErr;
  const productRows = recalls.flatMap((r) => r.products.map((p) => ({
    recall_id: r.id, name: p.name, barcode: p.barcode, pack_size: p.packSize,
    batch_codes: p.batchCodes, best_before: p.bestBefore, use_by: p.useBy, batch_notes: p.batchNotes,
  })));
  if (productRows.length) {
    const { error: insErr } = await db.from('recall_products').insert(productRows);
    if (insErr) throw insErr;
  }
  return recalls.filter((r) => !known.has(r.id));
}

async function collectSource(db: Db, source: string, fetcher: typeof fetchFsaSince): Promise<{ newRecalls: Recall[]; firstRun: boolean; error?: string }> {
  const { data: state } = await db.from('sync_state').select('*').eq('source', source).maybeSingle();
  const firstRun = !state?.last_seen_at;
  const firstRunDays = FIRST_RUN_DAYS_BY_SOURCE[source] ?? FIRST_RUN_DAYS;
  const since = state?.last_seen_at ?? new Date(Date.now() - firstRunDays * 86400_000).toISOString();
  const runStarted = new Date().toISOString();
  try {
    const recalls = await fetcher(fetch, since);
    const newRecalls = await saveRecalls(db, recalls);
    const latest = recalls.reduce((max, r) => (r.updatedAt > max ? r.updatedAt : max), since);
    await db.from('sync_state').upsert({ source, last_seen_at: latest, last_run_at: runStarted, last_error: null });
    return { newRecalls, firstRun };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    await db.from('sync_state').upsert({ source, last_seen_at: state?.last_seen_at ?? null, last_run_at: runStarted, last_error: message });
    return { newRecalls: [], firstRun, error: message };
  }
}

async function findMatches(db: Db, recall: Recall): Promise<Match[]> {
  const { data: profileRows, error: pErr } = await db
    .from('profiles')
    .select('user_id, categories, allergens, alert_timing')
    .or(`categories.ov.{${recall.categories.join(',')}},allergens.ov.{${recall.allergens.join(',') || '_none_'}}`);
  if (pErr) throw pErr;
  const profiles: UserProfile[] = (profileRows ?? []).map((p: Record<string, unknown>) => ({
    userId: p.user_id as string, categories: p.categories as string[],
    allergens: p.allergens as string[], alertTiming: p.alert_timing as 'instant' | 'daily',
  }));

  const { data: itemRows, error: cErr } = await db.rpc('cupboard_candidates', { p_recall_id: recall.id });
  if (cErr) throw cErr;
  const cupboard: CupboardItem[] = (itemRows ?? []).map((i: Record<string, unknown>) => ({
    id: i.id as number, userId: i.user_id as string, name: i.name as string,
    brand: (i.brand as string) ?? null, barcode: (i.barcode as string) ?? null,
    dismissedRecalls: (i.dismissed_recalls as string[]) ?? [],
  }));

  return matchRecall(recall, profiles, cupboard);
}

async function notify(db: Db, recall: Recall, matches: Match[], cupboardNames: Map<number, string>) {
  if (matches.length === 0) return { alerts: 0, pushed: 0 };

  const { data: inserted, error } = await db
    .from('user_alerts')
    .upsert(matches.map((m) => ({
      user_id: m.userId, recall_id: m.recallId, reason: m.reason,
      confidence: m.confidence, cupboard_item_id: m.cupboardItemId,
    })), { onConflict: 'user_id,recall_id', ignoreDuplicates: true })
    .select('id, user_id, reason');
  if (error) throw error;
  if (!inserted?.length) return { alerts: 0, pushed: 0 };

  // Cupboard and allergen alerts always go out straight away — they're about safety.
  // Category alerts respect the person's "daily summary" choice.
  const userIds = [...new Set(inserted.map((a: { user_id: string }) => a.user_id))];
  const { data: timings } = await db.from('profiles').select('user_id, alert_timing').in('user_id', userIds);
  const daily = new Set((timings ?? []).filter((t: { alert_timing: string }) => t.alert_timing === 'daily').map((t: { user_id: string }) => t.user_id));
  const toPush = inserted.filter((a: { user_id: string; reason: string }) => a.reason !== 'category' || !daily.has(a.user_id));
  if (!toPush.length) return { alerts: inserted.length, pushed: 0 };

  const { data: tokens } = await db.from('push_tokens').select('token, user_id').in('user_id', toPush.map((a: { user_id: string }) => a.user_id));
  const matchByUser = new Map(matches.map((m) => [m.userId, m]));
  const messages: PushMessage[] = (tokens ?? []).map((t: { token: string; user_id: string }) => {
    const m = matchByUser.get(t.user_id)!;
    const text = notificationText(recall, m, m.cupboardItemId ? cupboardNames.get(m.cupboardItemId) : undefined);
    return { to: t.token, ...text, data: { recallId: recall.id } };
  });

  const { sent, deadTokens, errors: pushErrors } = await sendPush(fetch, messages, Deno.env.get('EXPO_ACCESS_TOKEN') ?? undefined);
  if (pushErrors.length) console.error('Some alerts could not be sent:', pushErrors);
  if (deadTokens.length) await db.from('push_tokens').delete().in('token', deadTokens);
  await db.from('user_alerts').update({ pushed_at: new Date().toISOString() }).in('id', toPush.map((a: { id: number }) => a.id));
  return { alerts: inserted.length, pushed: sent };
}

Deno.serve(async (req) => {
  // Only our scheduler may run this.
  const secret = Deno.env.get('CRON_SECRET');
  if (!secret || req.headers.get('Authorization') !== `Bearer ${secret}`) {
    return new Response('Unauthorised', { status: 401 });
  }

  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false },
  });

  const report: Record<string, unknown> = { engine: ENGINE_VERSION };
  const started = Date.now();
  // Each entry keeps its own place in sync_state, so the name doesn't have to be a recall source.
  const SOURCES: Array<[string, typeof fetchFsaSince]> = [
    ['fsa', fetchFsaSince],
    ['opss', fetchOpssSince],
    ['mhra', fetchMhraSince],
    ['mhra-fsn', fetchFsnSince],
    ['vmd', fetchVmdSince],
    ['fss', fetchFssSince],
    ['hse', fetchHseSince],
    ['eu', fetchEuSince],
  ];
  const results = await Promise.all(SOURCES.map(([source, fetcher]) => collectSource(db, source, fetcher)));

  let alerts = 0;
  let pushed = 0;
  const errors: string[] = [];
  for (const [i, result] of results.entries()) {
    const source = SOURCES[i][0];
    report[source] = { newRecalls: result.newRecalls.length, firstRun: result.firstRun, error: result.error ?? null };
    if (result.error) errors.push(`${source}: ${result.error}`);
    // The first run loads history — don't notify anyone about old recalls.
    if (result.firstRun) continue;

    for (const recall of result.newRecalls) {
      try {
        const matches = await findMatches(db, recall);
        const itemIds = matches.map((m) => m.cupboardItemId).filter((id): id is number => id !== null);
        const names = new Map<number, string>();
        if (itemIds.length) {
          const { data } = await db.from('cupboard_items').select('id, name').in('id', itemIds);
          for (const row of data ?? []) names.set(row.id, row.name);
        }
        const r = await notify(db, recall, matches, names);
        alerts += r.alerts;
        pushed += r.pushed;
      } catch (err) {
        errors.push(`${recall.id}: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  }

  // Older recalls, a batch per source each run. Saved quietly: no alerts for these.
  try {
    report.backfill = await runBackfill({
      fetchFn: fetch,
      deadline: started + BACKFILL_SECONDS * 1000,
      load: async () => {
        const { data, error } = await db.from('backfill_state').select('key, from_date, next_offset, done');
        if (error) throw error;
        return (data ?? []).map((r: { key: string; from_date: string; next_offset: number; done: boolean }) =>
          ({ key: r.key, fromDate: r.from_date, offset: r.next_offset, done: r.done }) as BackfillState);
      },
      store: async (s) => {
        const { error } = await db.from('backfill_state').upsert({
          key: s.key, from_date: s.fromDate, next_offset: s.offset, done: s.done, updated_at: new Date().toISOString(),
        });
        if (error) throw error;
      },
      save: async (recalls) => { await saveRecalls(db, recalls); },
    });
  } catch (err) {
    errors.push(`backfill: ${err instanceof Error ? err.message : String(err)}`);
  }

  try {
    report.photos = await addPhotos(db);
  } catch (err) {
    errors.push(`photos: ${err instanceof Error ? err.message : String(err)}`);
  }

  report.alertsCreated = alerts;
  report.notificationsSent = pushed;
  report.errors = errors;
  return new Response(JSON.stringify(report, null, 2), {
    status: errors.length ? 207 : 200,
    headers: { 'Content-Type': 'application/json' },
  });
});

